diffs.replacement:
{
  "name": "NovaFit Pro Dashboard",
  "description": "A premium, high-performance SaaS dashboard for Personal Trainers to manage clients, workouts, and nutrition with a focus on productivity and modern aesthetics."
}

export type Status = 'active' | 'pending' | 'inactive' | 'completed' | 'warning';

export interface Client {
  id: string;
  name: string;
  avatar: string;
  plan: string;
  status: Status;
  lastActive: string;
  contact: string;
  progress: number;
}

export interface DashboardEvent {
  id: string;
  type: 'birthday' | 'check-in' | 'goal' | 'payment';
  clientId: string;
  clientName: string;
  title: string;
  time: string;
  isUrgent?: boolean;
}

export interface PendingItem {
  id: string;
  type: 'workout_submission' | 'physical_assessment' | 'nutrition_update';
  clientId: string;
  clientName: string;
  date: string;
  status: Status;
  details: string;
}

export interface Feedback {
  id: string;
  clientId: string;
  clientName: string;
  avatar: string;
  rating: number; // 1-5
  comment: string;
  date: string;
  read: boolean;
}

export interface Metric {
  label: string;
  value: string;
  trend: number; // percentage
  trendLabel: string;
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React from 'react';
import { MENU_ITEMS } from '../constants';
import { LogOut, Zap } from 'lucide-react';

interface SidebarProps {
  activeTab: string;
  setActiveTab: (id: string) => void;
  isOpen: boolean;
}

const Sidebar: React.FC<SidebarProps> = ({ activeTab, setActiveTab, isOpen }) => {
  return (
    <aside 
      className={`
        fixed left-0 top-0 h-full z-40 transition-all duration-300 ease-in-out
        ${isOpen ? 'translate-x-0 w-64' : '-translate-x-full w-64 lg:translate-x-0 lg:w-20 xl:w-64'}
        glass-panel border-r border-slate-200 dark:border-slate-800
        flex flex-col justify-between py-6
      `}
    >
      <div>
        {/* Logo Area */}
        <div className="flex items-center justify-center xl:justify-start xl:px-8 mb-10">
          <div className="w-10 h-10 bg-gradient-to-tr from-primary-600 to-primary-400 rounded-xl shadow-lg shadow-primary-500/30 flex items-center justify-center text-white font-bold text-xl shrink-0">
            <Zap size={24} fill="white" />
          </div>
          <span className="ml-3 font-bold text-xl tracking-tight hidden xl:block bg-gradient-to-r from-slate-800 to-slate-500 dark:from-white dark:to-slate-400 bg-clip-text text-transparent">
            NovaFit
          </span>
        </div>

        {/* Navigation Items */}
        <nav className="flex flex-col gap-2 px-3">
          {MENU_ITEMS.map((item) => {
            const isActive = activeTab === item.id;
            const Icon = item.icon;

            return (
              <button
                key={item.id}
                onClick={() => setActiveTab(item.id)}
                className={`
                  flex items-center px-4 py-3 rounded-xl transition-all duration-200 group relative overflow-hidden
                  ${isActive 
                    ? 'bg-primary-50 dark:bg-primary-900/20 text-primary-600 dark:text-primary-400 shadow-sm' 
                    : 'text-slate-500 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800/50 hover:text-slate-900 dark:hover:text-slate-200'}
                `}
              >
                {isActive && (
                  <div className="absolute left-0 top-1/2 -translate-y-1/2 w-1 h-8 bg-primary-500 rounded-r-full" />
                )}
                <Icon size={22} strokeWidth={isActive ? 2.5 : 2} className="shrink-0" />
                <span className={`ml-3 font-medium text-sm hidden xl:block ${isActive ? 'font-semibold' : ''}`}>
                  {item.label}
                </span>

                {/* Tooltip for collapsed mode */}
                <div className="absolute left-16 bg-slate-900 text-white text-xs px-2 py-1 rounded opacity-0 group-hover:opacity-100 xl:group-hover:opacity-0 pointer-events-none transition-opacity z-50 whitespace-nowrap lg:block hidden">
                   {item.label}
                </div>
              </button>
            );
          })}
        </nav>
      </div>

      {/* Footer / Logout */}
      <div className="px-3">
        <button className="flex items-center w-full px-4 py-3 rounded-xl text-slate-500 dark:text-slate-400 hover:bg-red-50 dark:hover:bg-red-900/10 hover:text-red-500 transition-colors">
          <LogOut size={22} />
          <span className="ml-3 font-medium text-sm hidden xl:block">Sair da Conta</span>
        </button>
      </div>
    </aside>
  );
};

export default Sidebar;

import React from 'react';
import { Search, Bell, Moon, Sun, Menu, ChevronDown } from 'lucide-react';

interface HeaderProps {
  isDarkMode: boolean;
  toggleTheme: () => void;
  toggleSidebar: () => void;
  title: string;
}

const Header: React.FC<HeaderProps> = ({ isDarkMode, toggleTheme, toggleSidebar, title }) => {
  return (
    <header className="sticky top-0 z-30 w-full px-6 py-4 flex items-center justify-between glass-panel border-b border-slate-200 dark:border-slate-800 transition-all">
      <div className="flex items-center gap-4">
        <button 
          onClick={toggleSidebar}
          className="lg:hidden p-2 text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg"
        >
          <Menu size={24} />
        </button>

        <h1 className="text-xl font-bold bg-gradient-to-r from-slate-900 to-slate-600 dark:from-white dark:to-slate-300 bg-clip-text text-transparent hidden sm:block">
          {title}
        </h1>
      </div>

      {/* Center Search - Dynamic Width */}
      <div className="hidden md:flex flex-1 max-w-lg mx-6 relative group">
        <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
          <Search size={18} className="text-slate-400 group-focus-within:text-primary-500 transition-colors" />
        </div>
        <input 
          type="text" 
          placeholder="Pesquisar clientes, planos ou tarefas..." 
          className="block w-full pl-10 pr-3 py-2.5 rounded-xl border-none bg-slate-100/50 dark:bg-slate-800/50 text-slate-900 dark:text-slate-100 placeholder-slate-400 focus:ring-2 focus:ring-primary-500/50 focus:bg-white dark:focus:bg-slate-800 transition-all text-sm shadow-inner"
        />
        <div className="absolute inset-y-0 right-2 flex items-center">
            <span className="text-xs text-slate-400 border border-slate-300 dark:border-slate-600 rounded px-1.5 py-0.5">⌘K</span>
        </div>
      </div>

      {/* Right Actions */}
      <div className="flex items-center gap-3 sm:gap-5">

        {/* Theme Toggle */}
        <button 
          onClick={toggleTheme} 
          className="p-2.5 rounded-full text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors relative overflow-hidden group"
          aria-label="Toggle Dark Mode"
        >
          <div className="relative z-10">
            {isDarkMode ? <Sun size={20} className="text-amber-400" /> : <Moon size={20} className="text-indigo-600" />}
          </div>
          <div className="absolute inset-0 bg-gradient-to-tr from-indigo-500/10 to-purple-500/10 opacity-0 group-hover:opacity-100 transition-opacity" />
        </button>

        {/* Notifications */}
        <button className="relative p-2.5 rounded-full text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors">
          <Bell size={20} />
          <span className="absolute top-2 right-2 w-2.5 h-2.5 bg-red-500 border-2 border-white dark:border-slate-900 rounded-full animate-pulse"></span>
        </button>

        {/* User Profile */}
        <div className="flex items-center gap-3 pl-2 border-l border-slate-200 dark:border-slate-700">
          <div className="text-right hidden sm:block">
            <p className="text-sm font-semibold text-slate-800 dark:text-white">Ricardo Treinador</p>
            <p className="text-xs text-slate-500 dark:text-slate-400">Personal Trainer Pro</p>
          </div>
          <button className="flex items-center gap-2 focus:outline-none">
            <img 
              src="https://picsum.photos/100/100?random=100" 
              alt="Profile" 
              className="w-10 h-10 rounded-full ring-2 ring-white dark:ring-slate-700 shadow-lg object-cover"
            />
            <ChevronDown size={16} className="text-slate-400 hidden sm:block" />
          </button>
        </div>
      </div>
    </header>
  );
};

export default Header;

import React from 'react';
import { TrendingUp, TrendingDown } from 'lucide-react';
import { Metric } from '../../types';

interface StatCardProps {
  metric: Metric;
}

const StatCard: React.FC<StatCardProps> = ({ metric }) => {
  const isPositive = metric.trend >= 0;

  return (
    <div className="glass-card rounded-2xl p-6 relative overflow-hidden group hover:shadow-lg hover:shadow-primary-500/10 transition-all duration-300 transform hover:-translate-y-1">
      {/* Background Decor */}
      <div className="absolute -right-6 -top-6 w-24 h-24 bg-gradient-to-br from-primary-400/20 to-purple-500/20 rounded-full blur-2xl group-hover:bg-primary-400/30 transition-colors" />

      <h3 className="text-slate-500 dark:text-slate-400 text-sm font-medium mb-2 uppercase tracking-wider">
        {metric.label}
      </h3>

      <div className="flex items-end justify-between relative z-10">
        <span className="text-3xl font-bold text-slate-800 dark:text-white tracking-tight">
          {metric.value}
        </span>

        <div className={`flex items-center px-2 py-1 rounded-lg text-xs font-semibold ${
          isPositive 
            ? 'text-emerald-600 bg-emerald-50 dark:bg-emerald-900/30 dark:text-emerald-400' 
            : 'text-rose-600 bg-rose-50 dark:bg-rose-900/30 dark:text-rose-400'
        }`}>
          {isPositive ? <TrendingUp size={14} className="mr-1" /> : <TrendingDown size={14} className="mr-1" />}
          {Math.abs(metric.trend)}%
        </div>
      </div>

      <p className="text-xs text-slate-400 mt-2 font-medium">
        {metric.trendLabel}
      </p>
    </div>
  );
};

export default StatCard;

import React from 'react';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { CHART_DATA } from '../../constants';

const ActivityChart: React.FC = () => {
  return (
    <div className="h-[300px] w-full">
      <ResponsiveContainer width="100%" height="100%">
        <AreaChart
          data={CHART_DATA}
          margin={{ top: 10, right: 0, left: -20, bottom: 0 }}
        >
          <defs>
            <linearGradient id="colorTreinos" x1="0" y1="0" x2="0" y2="1">
              <stop offset="5%" stopColor="#0ea5e9" stopOpacity={0.3}/>
              <stop offset="95%" stopColor="#0ea5e9" stopOpacity={0}/>
            </linearGradient>
            <linearGradient id="colorCheckins" x1="0" y1="0" x2="0" y2="1">
              <stop offset="5%" stopColor="#8b5cf6" stopOpacity={0.3}/>
              <stop offset="95%" stopColor="#8b5cf6" stopOpacity={0}/>
            </linearGradient>
          </defs>
          <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="rgba(203, 213, 225, 0.3)" />
          <XAxis 
            dataKey="name" 
            axisLine={false} 
            tickLine={false} 
            tick={{ fill: '#94a3b8', fontSize: 12 }} 
            dy={10}
          />
          <YAxis 
            axisLine={false} 
            tickLine={false} 
            tick={{ fill: '#94a3b8', fontSize: 12 }} 
          />
          <Tooltip 
            contentStyle={{ 
              backgroundColor: 'rgba(30, 41, 59, 0.9)', 
              borderColor: 'rgba(255,255,255,0.1)',
              borderRadius: '12px',
              color: '#fff',
              boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1)' 
            }}
            itemStyle={{ fontSize: '13px', fontWeight: 500 }}
            cursor={{ stroke: 'rgba(148, 163, 184, 0.5)', strokeWidth: 1, strokeDasharray: '4 4' }}
          />
          <Area 
            type="monotone" 
            dataKey="treinos" 
            name="Treinos Submetidos"
            stroke="#0ea5e9" 
            strokeWidth={3}
            fillOpacity={1} 
            fill="url(#colorTreinos)" 
          />
          <Area 
            type="monotone" 
            dataKey="checkins" 
            name="Check-ins"
            stroke="#8b5cf6" 
            strokeWidth={3}
            fillOpacity={1} 
            fill="url(#colorCheckins)" 
          />
        </AreaChart>
      </ResponsiveContainer>
    </div>
  );
};

export default ActivityChart;

import React from 'react';
import { MOCK_EVENTS } from '../../constants';
import { Calendar, AlertCircle, Gift, CheckCircle2 } from 'lucide-react';

const EventList: React.FC = () => {
  const getIcon = (type: string) => {
    switch(type) {
      case 'birthday': return <Gift size={18} className="text-pink-500" />;
      case 'check-in': return <CheckCircle2 size={18} className="text-emerald-500" />;
      case 'payment': return <AlertCircle size={18} className="text-amber-500" />;
      default: return <Calendar size={18} className="text-primary-500" />;
    }
  };

  return (
    <div className="space-y-4">
      {MOCK_EVENTS.map(event => (
        <div key={event.id} className="flex items-center p-3 rounded-xl bg-slate-50 dark:bg-slate-800/50 hover:bg-white dark:hover:bg-slate-800 border border-slate-100 dark:border-slate-700 transition-colors cursor-pointer group">
          <div className={`
            w-10 h-10 rounded-full flex items-center justify-center shrink-0
            ${event.type === 'birthday' ? 'bg-pink-100 dark:bg-pink-900/20' : ''}
            ${event.type === 'check-in' ? 'bg-emerald-100 dark:bg-emerald-900/20' : ''}
            ${event.type === 'payment' ? 'bg-amber-100 dark:bg-amber-900/20' : ''}
            ${event.type === 'goal' ? 'bg-primary-100 dark:bg-primary-900/20' : ''}
          `}>
            {getIcon(event.type)}
          </div>
          <div className="ml-3 flex-1">
            <h4 className="text-sm font-semibold text-slate-800 dark:text-slate-100 group-hover:text-primary-500 transition-colors">
              {event.clientName}
            </h4>
            <p className="text-xs text-slate-500 dark:text-slate-400">{event.title}</p>
          </div>
          <div className="text-right">
            <span className={`text-xs font-medium px-2 py-1 rounded-full ${event.isUrgent ? 'bg-red-100 text-red-600 dark:bg-red-900/30 dark:text-red-400 animate-pulse' : 'bg-slate-200 dark:bg-slate-700 text-slate-600 dark:text-slate-300'}`}>
              {event.time}
            </span>
          </div>
        </div>
      ))}
    </div>
  );
};

export default EventList;

import React from 'react';
import { MOCK_PENDING } from '../../constants';
import { ChevronRight, FileText, Activity, Utensils } from 'lucide-react';

const PendingTable: React.FC = () => {
  const getTypeConfig = (type: string) => {
    switch(type) {
      case 'workout_submission': return { label: 'Treino', icon: Activity, color: 'text-blue-500', bg: 'bg-blue-500/10' };
      case 'physical_assessment': return { label: 'Avaliação', icon: FileText, color: 'text-purple-500', bg: 'bg-purple-500/10' };
      case 'nutrition_update': return { label: 'Nutrição', icon: Utensils, color: 'text-emerald-500', bg: 'bg-emerald-500/10' };
      default: return { label: 'Geral', icon: FileText, color: 'text-slate-500', bg: 'bg-slate-500/10' };
    }
  };

  return (
    <div className="overflow-x-auto">
      <table className="w-full text-left border-collapse">
        <thead>
          <tr className="text-xs font-semibold text-slate-400 border-b border-slate-200 dark:border-slate-700 uppercase tracking-wider">
            <th className="px-4 py-3">Tipo</th>
            <th className="px-4 py-3">Cliente</th>
            <th className="px-4 py-3">Detalhes</th>
            <th className="px-4 py-3 text-right">Ação</th>
          </tr>
        </thead>
        <tbody className="text-sm divide-y divide-slate-100 dark:divide-slate-800">
          {MOCK_PENDING.length === 0 ? (
             <tr>
               <td colSpan={4} className="px-4 py-8 text-center text-slate-500 italic">Hoje não existem registos pendentes.</td>
             </tr>
          ) : (
            MOCK_PENDING.map((item) => {
              const config = getTypeConfig(item.type);
              const Icon = config.icon;
              return (
                <tr key={item.id} className="group hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">
                  <td className="px-4 py-3">
                    <div className={`flex items-center gap-2 px-2 py-1 rounded-md w-fit ${config.bg} ${config.color}`}>
                      <Icon size={14} />
                      <span className="font-medium text-xs">{config.label}</span>
                    </div>
                  </td>
                  <td className="px-4 py-3 font-medium text-slate-700 dark:text-slate-200">
                    {item.clientName}
                  </td>
                  <td className="px-4 py-3 text-slate-500 dark:text-slate-400">
                    {item.details}
                  </td>
                  <td className="px-4 py-3 text-right">
                    <button className="text-primary-600 hover:text-primary-700 dark:text-primary-400 dark:hover:text-primary-300 font-medium text-xs flex items-center justify-end gap-1 ml-auto group-hover:underline">
                      Rever <ChevronRight size={14} />
                    </button>
                  </td>
                </tr>
              );
            })
          )}
        </tbody>
      </table>

      {/* Pagination Mock */}
      <div className="mt-4 flex justify-between items-center px-4">
        <span className="text-xs text-slate-400">A mostrar 3 de 3</span>
        <div className="flex gap-2">
          <button disabled className="px-2 py-1 text-xs rounded border border-slate-200 dark:border-slate-700 text-slate-300 dark:text-slate-600 cursor-not-allowed">Anterior</button>
          <button disabled className="px-2 py-1 text-xs rounded border border-slate-200 dark:border-slate-700 text-slate-300 dark:text-slate-600 cursor-not-allowed">Seguinte</button>
        </div>
      </div>
    </div>
  );
};

export default PendingTable;

import React from 'react';
import { MOCK_FEEDBACK } from '../../constants';
import { Star, MessageSquare } from 'lucide-react';

const FeedbackList: React.FC = () => {
  return (
    <div className="space-y-4">
      {MOCK_FEEDBACK.map(item => (
        <div key={item.id} className="relative p-4 rounded-xl bg-gradient-to-r from-white to-slate-50 dark:from-slate-800 dark:to-slate-800/50 border border-slate-100 dark:border-slate-700 shadow-sm hover:shadow-md transition-all duration-300">
          {!item.read && (
            <span className="absolute top-4 right-4 w-2 h-2 bg-primary-500 rounded-full animate-pulse" />
          )}

          <div className="flex items-start gap-3">
            <img src={item.avatar} alt={item.clientName} className="w-10 h-10 rounded-full object-cover ring-2 ring-white dark:ring-slate-700 shadow" />

            <div className="flex-1">
              <div className="flex justify-between items-start">
                <h4 className="text-sm font-bold text-slate-800 dark:text-slate-100">{item.clientName}</h4>
                <span className="text-[10px] uppercase tracking-wide text-slate-400 font-medium">{item.date}</span>
              </div>

              <div className="flex gap-0.5 my-1">
                {[1, 2, 3, 4, 5].map((star) => (
                  <Star 
                    key={star} 
                    size={12} 
                    className={star <= item.rating ? "fill-amber-400 text-amber-400" : "text-slate-200 dark:text-slate-700"} 
                  />
                ))}
              </div>

              <div className="relative mt-2 p-2 bg-slate-100 dark:bg-slate-900/50 rounded-lg rounded-tl-none text-xs text-slate-600 dark:text-slate-300 italic">
                "{item.comment}"
                <MessageSquare size={12} className="absolute -top-1 -left-1 text-slate-300 dark:text-slate-600 transform -scale-x-100" />
              </div>
            </div>
          </div>
        </div>
      ))}
      <button className="w-full py-2 text-xs font-medium text-slate-500 hover:text-primary-500 transition-colors border-t border-slate-100 dark:border-slate-700 mt-2">
        Ver todos os feedbacks
      </button>
    </div>
  );
};

export default FeedbackList;

import React, { useState } from 'react';
import { MOCK_METRICS } from '../constants';
import StatCard from './dashboard/StatCard';
import ActivityChart from './dashboard/ActivityChart';
import EventList from './dashboard/EventList';
import PendingTable from './dashboard/PendingTable';
import FeedbackList from './dashboard/FeedbackList';
import { Filter, Search, MoreHorizontal } from 'lucide-react';

const DashboardView: React.FC = () => {
  const [filterPeriod, setFilterPeriod] = useState('Semanal');

  return (
    <div className="space-y-8 animate-fade-in pb-10">

      {/* Metrics Row */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {MOCK_METRICS.map((metric, idx) => (
          <StatCard key={idx} metric={metric} />
        ))}
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-6">

        {/* Main Chart Section (Takes 2/3 on big screens) */}
        <div className="xl:col-span-2 glass-card rounded-2xl p-6 flex flex-col h-[450px]">
          <div className="flex justify-between items-center mb-6">
            <div>
              <h2 className="text-lg font-bold text-slate-800 dark:text-white">Performance Global</h2>
              <p className="text-xs text-slate-500 dark:text-slate-400">Atividade dos clientes e adesão aos planos</p>
            </div>

            {/* Chart Filters */}
            <div className="flex bg-slate-100 dark:bg-slate-800 p-1 rounded-lg">
              {['Semanal', 'Mensal'].map((period) => (
                <button
                  key={period}
                  onClick={() => setFilterPeriod(period)}
                  className={`px-3 py-1 text-xs font-medium rounded-md transition-all ${
                    filterPeriod === period 
                      ? 'bg-white dark:bg-slate-600 text-primary-600 dark:text-white shadow-sm' 
                      : 'text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200'
                  }`}
                >
                  {period}
                </button>
              ))}
            </div>
          </div>
          <div className="flex-1 min-h-0">
             <ActivityChart />
          </div>
        </div>

        {/* Side Widget: Events of the Day */}
        <div className="glass-card rounded-2xl p-6 flex flex-col h-[450px]">
          <div className="flex justify-between items-center mb-6">
            <h2 className="text-lg font-bold text-slate-800 dark:text-white">Agenda Hoje</h2>
            <button className="text-slate-400 hover:text-primary-500 transition-colors">
              <MoreHorizontal size={18} />
            </button>
          </div>
          <div className="flex-1 overflow-y-auto pr-2 custom-scrollbar">
            <EventList />
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-2 gap-6">

        {/* Pending Validations Section */}
        <div className="glass-card rounded-2xl p-0 overflow-hidden flex flex-col">
          <div className="p-6 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center bg-white/50 dark:bg-slate-800/30">
            <div>
              <h2 className="text-lg font-bold text-slate-800 dark:text-white flex items-center gap-2">
                Validações Pendentes
                <span className="px-2 py-0.5 rounded-full bg-amber-100 dark:bg-amber-900/40 text-amber-600 dark:text-amber-400 text-xs font-bold">3</span>
