import React, { useState, useEffect } from 'react';
import { X, Upload, Save, AlertCircle, Plus, Trash2, Link as LinkIcon, Video, FileText } from 'lucide-react';
import { Exercise, ExerciseVideo, VideoType } from '../../types';
import { MUSCLE_GROUPS, EQUIPMENT_TYPES, DIFFICULTY_LEVELS, EXERCISE_TYPES, DESCRIPTION_TEMPLATES } from '../../constants';

interface ExerciseModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (exercise: Omit<Exercise, 'id' | 'isDeleted'>) => void;
  initialData?: Exercise | null;
}

const ExerciseModal: React.FC<ExerciseModalProps> = ({ isOpen, onClose, onSave, initialData }) => {
  const [formData, setFormData] = useState<{
    name: string;
    image: string;
    muscleGroup: string;
    type: 'Indefinido' | 'Alongamento' | 'Mobilidade' | 'Força';
    equipment: string;
    difficulty: 'Iniciante' | 'Intermédio' | 'Avançado';
    videos: ExerciseVideo[];
    description: string;
    notes: string;
  }>({
    name: '',
    image: '',
    muscleGroup: MUSCLE_GROUPS[0],
    type: 'Indefinido',
    equipment: EQUIPMENT_TYPES[0],
    difficulty: 'Iniciante',
    videos: [{ type: 'link', url: '' }],
    description: '',
    notes: ''
  });

  useEffect(() => {
    if (initialData) {
      setFormData({
        name: initialData.name,
        image: initialData.image,
        muscleGroup: initialData.muscleGroup,
        type: initialData.type || 'Indefinido',
        equipment: initialData.equipment,
        difficulty: initialData.difficulty,
        videos: initialData.videos && initialData.videos.length > 0 ? initialData.videos : [{ type: 'link', url: '' }],
        description: initialData.description,
        notes: initialData.notes || ''
      });
    } else {
      setFormData({
        name: '',
        image: '',
        muscleGroup: MUSCLE_GROUPS[0],
        type: 'Indefinido',
        equipment: EQUIPMENT_TYPES[0],
        difficulty: 'Iniciante',
        videos: [{ type: 'link', url: '' }],
        description: '',
        notes: ''
      });
    }
  }, [initialData, isOpen]);

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave({
      ...formData,
      image: formData.image || 'https://images.unsplash.com/photo-1517836357463-d25dfeac3438?auto=format&fit=crop&q=80&w=200&h=200' // Fallback image
    });
    onClose();
  };

  const addVideoSlot = () => {
    if (formData.videos.length < 2) {
      setFormData(prev => ({
        ...prev,
        videos: [...prev.videos, { type: 'link', url: '' }]
      }));
    }
  };

  const removeVideoSlot = (index: number) => {
    setFormData(prev => ({
      ...prev,
      videos: prev.videos.filter((_, i) => i !== index)
    }));
  };

  const updateVideo = (index: number, field: keyof ExerciseVideo, value: string) => {
    setFormData(prev => ({
      ...prev,
      videos: prev.videos.map((v, i) => i === index ? { ...v, [field]: value } : v)
    }));
  };

  const applyTemplate = (templateKey: keyof typeof DESCRIPTION_TEMPLATES) => {
    setFormData(prev => ({
      ...prev,
      description: DESCRIPTION_TEMPLATES[templateKey]
    }));
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 sm:p-6">
      <div 
        className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm transition-opacity" 
        onClick={onClose}
      />

      <div className="relative w-full max-w-3xl bg-white dark:bg-slate-900 rounded-2xl shadow-2xl ring-1 ring-slate-200 dark:ring-slate-800 flex flex-col max-h-[90vh] overflow-hidden animate-fade-in-up">

        {/* Header */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-slate-100 dark:border-slate-800 bg-white dark:bg-slate-900 z-10">
          <div>
            <h2 className="text-xl font-bold text-slate-900 dark:text-white">
              {initialData ? 'Editar Exercício' : 'Novo Exercício'}
            </h2>
            <p className="text-xs text-slate-500 dark:text-slate-400">Preencha os detalhes técnicos do movimento.</p>
          </div>
          <button 
            onClick={onClose}
            className="p-2 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg transition-colors"
          >
            <X size={20} />
          </button>
        </div>

        {/* Form Body */}
        <div className="flex-1 overflow-y-auto p-6 custom-scrollbar bg-slate-50/50 dark:bg-slate-900/50">
          <form id="exercise-form" onSubmit={handleSubmit} className="space-y-6">

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {/* Image Upload Area */}
              <div className="col-span-1 md:col-span-2">
                 <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">Imagem de Capa</label>
                 <div className="flex items-start gap-4">
                    <div className="w-24 h-24 rounded-xl bg-slate-100 dark:bg-slate-800 border-2 border-dashed border-slate-300 dark:border-slate-700 flex items-center justify-center shrink-0 overflow-hidden group hover:border-primary-500 transition-colors">
                       {formData.image ? (
                         <img src={formData.image} alt="Preview" className="w-full h-full object-cover" />
                       ) : (
                         <Upload size={24} className="text-slate-400 group-hover:text-primary-500 transition-colors" />
                       )}
                    </div>
                    <div className="flex-1">
                      <input 
                        type="text" 
                        placeholder="URL da imagem (ex: unsplash.com/...)" 
                        value={formData.image}
                        onChange={(e) => setFormData({...formData, image: e.target.value})}
                        className="w-full px-3 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm focus:ring-2 focus:ring-primary-500 outline-none transition-all"
                      />
                      <p className="text-xs text-slate-500 mt-2">Cole um link direto para uma imagem ou deixe vazio para usar a imagem padrão.</p>
                    </div>
                 </div>
              </div>

              <div className="col-span-2 md:col-span-1">
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Nome do Exercício</label>
                <input 
                  required
                  type="text" 
                  value={formData.name}
                  onChange={(e) => setFormData({...formData, name: e.target.value})}
                  className="w-full px-4 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm focus:ring-2 focus:ring-primary-500 outline-none transition-all"
                  placeholder="Ex: Supino Inclinado com Halteres"
                />
              </div>

              <div className="col-span-2 md:col-span-1">
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Tipo</label>
                <select 
                  value={formData.type}
                  onChange={(e) => setFormData({...formData, type: e.target.value as any})}
                  className="w-full px-4 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm focus:ring-2 focus:ring-primary-500 outline-none transition-all"
                >
                  {EXERCISE_TYPES.map(t => <option key={t} value={t}>{t}</option>)}
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Grupo Muscular</label>
                <select 
                  value={formData.muscleGroup}
                  onChange={(e) => setFormData({...formData, muscleGroup: e.target.value})}
                  className="w-full px-4 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm focus:ring-2 focus:ring-primary-500 outline-none transition-all"
                >
                  {MUSCLE_GROUPS.map(g => <option key={g} value={g}>{g}</option>)}
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Equipamento</label>
                <select 
                  value={formData.equipment}
                  onChange={(e) => setFormData({...formData, equipment: e.target.value})}
                  className="w-full px-4 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm focus:ring-2 focus:ring-primary-500 outline-none transition-all"
                >
                  {EQUIPMENT_TYPES.map(t => <option key={t} value={t}>{t}</option>)}
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Nível de Dificuldade</label>
                <div className="flex gap-2">
                  {DIFFICULTY_LEVELS.map((level) => (
                    <button
                      key={level}
                      type="button"
                      onClick={() => setFormData({...formData, difficulty: level as any})}
                      className={`
                        flex-1 py-2 text-xs font-medium rounded-lg border transition-all
                        ${formData.difficulty === level 
                          ? 'bg-primary-500 border-primary-500 text-white shadow-md shadow-primary-500/20' 
                          : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-500 hover:border-primary-300'}
                      `}
                    >
                      {level}
                    </button>
                  ))}
                </div>
              </div>

              {/* Videos Section */}
              <div className="col-span-2 bg-white dark:bg-slate-800 p-4 rounded-xl border border-slate-200 dark:border-slate-700">
                <div className="flex justify-between items-center mb-3">
                   <label className="block text-sm font-bold text-slate-700 dark:text-slate-300">Vídeos de Demonstração (Máx. 2)</label>
                   {formData.videos.length < 2 && (
                     <button 
                        type="button" 
                        onClick={addVideoSlot}
                        className="text-xs flex items-center gap-1 text-primary-600 font-medium hover:text-primary-700 transition-colors"
                     >
                        <Plus size={14} /> Adicionar Vídeo
                     </button>
                   )}
                </div>

                <div className="space-y-3">
                  {formData.videos.map((video, index) => (
                    <div key={index} className="flex flex-col sm:flex-row gap-3 p-3 bg-slate-50 dark:bg-slate-900/50 rounded-lg border border-slate-100 dark:border-slate-700/50">
                       <div className="flex items-center gap-2 sm:w-40 shrink-0">
                          <button
                            type="button"
                            onClick={() => updateVideo(index, 'type', 'link')}
                            className={`flex-1 flex justify-center items-center py-1.5 rounded-md text-xs font-medium transition-all ${video.type === 'link' ? 'bg-primary-100 text-primary-700 dark:bg-primary-900/30 dark:text-primary-400' : 'text-slate-500 hover:bg-slate-200 dark:hover:bg-slate-800'}`}
                          >
                             <LinkIcon size={14} className="mr-1" /> Link
                          </button>
                          <button
                            type="button"
                            onClick={() => updateVideo(index, 'type', 'upload')}
                            className={`flex-1 flex justify-center items-center py-1.5 rounded-md text-xs font-medium transition-all ${video.type === 'upload' ? 'bg-primary-100 text-primary-700 dark:bg-primary-900/30 dark:text-primary-400' : 'text-slate-500 hover:bg-slate-200 dark:hover:bg-slate-800'}`}
                          >
                             <Video size={14} className="mr-1" /> Upload
                          </button>
                       </div>

                       <div className="flex-1">
                          {video.type === 'link' ? (
                             <input 
                               type="url" 
                               value={video.url}
                               onChange={(e) => updateVideo(index, 'url', e.target.value)}
                               className="w-full px-3 py-1.5 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-xs focus:ring-2 focus:ring-primary-500 outline-none transition-all"
                               placeholder="https://youtube.com/..."
                             />
                          ) : (
                             <div className="flex items-center justify-center w-full px-3 py-1.5 border border-dashed border-slate-300 dark:border-slate-600 rounded-lg bg-slate-100 dark:bg-slate-800 text-xs text-slate-500 hover:bg-slate-200 dark:hover:bg-slate-700 cursor-pointer transition-colors">
                                <span className="flex items-center gap-2"><Upload size={12}/> Selecionar Ficheiro (MP4, MOV)</span>
                             </div>
                          )}
                       </div>

                       <button 
                         type="button"
                         onClick={() => removeVideoSlot(index)}
                         className="p-1.5 text-slate-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition-colors"
                         title="Remover"
                       >
                         <Trash2 size={16} />
                       </button>
                    </div>
                  ))}
                  {formData.videos.length === 0 && (
                    <p className="text-xs text-slate-400 italic text-center py-2">Nenhum vídeo adicionado.</p>
                  )}
                </div>
              </div>

              {/* Description with Templates */}
              <div className="col-span-2">
                <div className="flex flex-wrap justify-between items-end mb-2 gap-2">
                   <label className="block text-sm font-medium text-slate-700 dark:text-slate-300">Descrição Técnica</label>
                   <div className="flex items-center gap-2">
                      <span className="text-[10px] uppercase font-bold text-slate-400 tracking-wider">Templates:</span>
                      <button type="button" onClick={() => applyTemplate('default')} className="text-[10px] px-2 py-1 bg-slate-100 dark:bg-slate-800 hover:bg-primary-50 dark:hover:bg-primary-900/20 hover:text-primary-600 rounded border border-slate-200 dark:border-slate-700 transition-colors">Padrão</button>
                      <button type="button" onClick={() => applyTemplate('strength')} className="text-[10px] px-2 py-1 bg-slate-100 dark:bg-slate-800 hover:bg-primary-50 dark:hover:bg-primary-900/20 hover:text-primary-600 rounded border border-slate-200 dark:border-slate-700 transition-colors">Força</button>
                      <button type="button" onClick={() => applyTemplate('mobility')} className="text-[10px] px-2 py-1 bg-slate-100 dark:bg-slate-800 hover:bg-primary-50 dark:hover:bg-primary-900/20 hover:text-primary-600 rounded border border-slate-200 dark:border-slate-700 transition-colors">Mobilidade</button>
                   </div>
                </div>
                <div className="relative">
                  <FileText size={16} className="absolute left-3 top-3 text-slate-400 pointer-events-none" />
                  <textarea 
                    rows={6}
                    value={formData.description}
                    onChange={(e) => setFormData({...formData, description: e.target.value})}
                    className="w-full pl-9 pr-4 py-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm focus:ring-2 focus:ring-primary-500 outline-none transition-all resize-none leading-relaxed"
                    placeholder="Instruções passo-a-passo da execução..."
                  />
                </div>
              </div>

              <div className="col-span-2">
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Observações para o Cliente (Opcional)</label>
                <div className="relative">
                  <AlertCircle size={16} className="absolute left-3 top-3 text-slate-400 pointer-events-none" />
                  <textarea 
                    rows={3}
                    value={formData.notes}
                    onChange={(e) => setFormData({...formData, notes: e.target.value})}
                    className="w-full pl-9 pr-4 py-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm focus:ring-2 focus:ring-primary-500 outline-none transition-all resize-none"
                    placeholder="Dicas de segurança ou variantes..."
                  />
                </div>
              </div>

            </div>
          </form>
        </div>

        {/* Footer */}
        <div className="px-6 py-4 bg-white dark:bg-slate-900 border-t border-slate-100 dark:border-slate-800 flex justify-end gap-3 z-10">
          <button 
            type="button" 
            onClick={onClose}
            className="px-4 py-2 text-sm font-medium text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg transition-colors"
          >
            Cancelar
          </button>
          <button 
            form="exercise-form"
            type="submit"
            className="flex items-center gap-2 px-6 py-2 text-sm font-medium text-white bg-primary-600 hover:bg-primary-500 active:bg-primary-700 rounded-lg shadow-lg shadow-primary-500/20 transition-all transform hover:-translate-y-0.5"
          >
            <Save size={18} />
            Guardar Exercício
          </button>
        </div>

      </div>
    </div>
  );
};

export default ExerciseModal;

import React, { useState, useMemo } from 'react';
import { 
  Search, 
  Plus, 
  Filter, 
  PlayCircle, 
  Trash2, 
  Edit2, 
  RotateCcw, 
  Youtube, 
  MoreVertical,
  Dumbbell,
  LayoutGrid
} from 'lucide-react';
import { Exercise } from '../../types';
import { MOCK_EXERCISES, MUSCLE_GROUPS, DIFFICULTY_LEVELS } from '../../constants';
import ExerciseModal from './ExerciseModal';

const ExercisesView: React.FC = () => {
  // State
  const [exercises, setExercises] = useState<Exercise[]>(MOCK_EXERCISES);
  const [searchQuery, setSearchQuery] = useState('');
  const [showDeleted, setShowDeleted] = useState(false);
  const [filterMuscle, setFilterMuscle] = useState('Todos');
  const [filterDifficulty, setFilterDifficulty] = useState('Todos');
  const [sortOrder, setSortOrder] = useState<'name' | 'muscle'>('name');

  // Modal State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingExercise, setEditingExercise] = useState<Exercise | null>(null);

  // Handlers
  const handleAdd = () => {
    setEditingExercise(null);
    setIsModalOpen(true);
  };

  const handleEdit = (exercise: Exercise) => {
    setEditingExercise(exercise);
    setIsModalOpen(true);
  };

  const handleSave = (exerciseData: Omit<Exercise, 'id' | 'isDeleted'>) => {
    if (editingExercise) {
      // Update existing
      setExercises(prev => prev.map(ex => 
        ex.id === editingExercise.id ? { ...ex, ...exerciseData } : ex
      ));
    } else {
      // Create new
      const newExercise: Exercise = {
        ...exerciseData,
        id: Math.random().toString(36).substr(2, 9),
        isDeleted: false
      };
      setExercises(prev => [newExercise, ...prev]);
    }
  };

  const toggleDelete = (id: string) => {
    setExercises(prev => prev.map(ex => {
      if (ex.id === id) {
        return { ...ex, isDeleted: !ex.isDeleted };
      }
      return ex;
    }));
  };

  const handleDeletePermanent = (id: string) => {
    if (confirm('Tem a certeza que deseja eliminar permanentemente este exercício?')) {
      setExercises(prev => prev.filter(ex => ex.id !== id));
    }
  };

  // Filter Logic
  const filteredExercises = useMemo(() => {
    return exercises
      .filter(ex => {
        if (!showDeleted && ex.isDeleted) return false;
        if (showDeleted && !ex.isDeleted) return false;

        const matchesSearch = ex.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                              ex.muscleGroup.toLowerCase().includes(searchQuery.toLowerCase());
        const matchesMuscle = filterMuscle === 'Todos' || ex.muscleGroup === filterMuscle;
        const matchesDifficulty = filterDifficulty === 'Todos' || ex.difficulty === filterDifficulty;

        return matchesSearch && matchesMuscle && matchesDifficulty;
      })
      .sort((a, b) => {
        if (sortOrder === 'name') return a.name.localeCompare(b.name);
        return a.muscleGroup.localeCompare(b.muscleGroup);
      });
  }, [exercises, searchQuery, showDeleted, filterMuscle, filterDifficulty, sortOrder]);

  // Visual Helpers
  const getDifficultyColor = (diff: string) => {
    switch (diff) {
      case 'Iniciante': return 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400';
      case 'Intermédio': return 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400';
      case 'Avançado': return 'bg-purple-100 text-purple-700 dark:bg-purple-900/30 dark:text-purple-400';
      default: return 'bg-slate-100 text-slate-700';
    }
  };

  return (
    <div className="space-y-6 animate-fade-in pb-20">

      {/* Top Toolbar */}
      <div className="glass-card rounded-2xl p-4 flex flex-col md:flex-row justify-between items-center gap-4 sticky top-0 z-20">

        {/* Left: Search & Toggles */}
        <div className="flex flex-col sm:flex-row gap-3 w-full md:w-auto">
          <div className="relative group min-w-[280px]">
            <Search size={18} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-primary-500 transition-colors" />
            <input 
              type="text" 
              placeholder="Pesquisar exercícios..." 
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-10 pr-4 py-2.5 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-primary-500 outline-none transition-all text-sm"
            />
          </div>

          <button 
            onClick={() => setShowDeleted(!showDeleted)}
            className={`
              flex items-center justify-center px-4 py-2.5 rounded-xl border text-sm font-medium transition-all
              ${showDeleted 
                ? 'bg-amber-50 border-amber-200 text-amber-600 dark:bg-amber-900/20 dark:border-amber-800 dark:text-amber-400' 
                : 'bg-white border-slate-200 text-slate-600 dark:bg-slate-800/50 dark:border-slate-700 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-slate-800'}
            `}
          >
            <Trash2 size={16} className="mr-2" />
            {showDeleted ? 'Ocultar Eliminados' : 'Mostrar Eliminados'}
          </button>
        </div>

        {/* Right: Actions */}
        <div className="flex gap-3 w-full md:w-auto justify-end">
          <button className="flex items-center px-4 py-2.5 bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-200 rounded-xl font-medium text-sm hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors">
            <Youtube size={18} className="mr-2 text-red-500" />
            Verificar Vídeos
          </button>

          <button 
            onClick={handleAdd}
            className="flex items-center px-5 py-2.5 bg-gradient-to-r from-primary-600 to-primary-500 text-white rounded-xl font-bold text-sm shadow-lg shadow-primary-500/25 hover:shadow-primary-500/40 hover:-translate-y-0.5 active:translate-y-0 transition-all"
          >
            <Plus size={18} className="mr-2" />
            Adicionar
          </button>
        </div>
      </div>

      {/* Filters Bar */}
      <div className="flex flex-wrap items-center gap-3 py-2 overflow-x-auto no-scrollbar">
        <div className="flex items-center text-slate-500 text-xs font-semibold uppercase tracking-wider mr-2">
          <Filter size={14} className="mr-1" /> Filtros:
        </div>

        <select 
          value={filterMuscle}
          onChange={(e) => setFilterMuscle(e.target.value)}
          className="px-3 py-1.5 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm text-slate-700 dark:text-slate-300 outline-none focus:border-primary-500"
        >
          <option value="Todos">Todos os Músculos</option>
          {MUSCLE_GROUPS.map(m => <option key={m} value={m}>{m}</option>)}
        </select>

        <select 
          value={filterDifficulty}
          onChange={(e) => setFilterDifficulty(e.target.value)}
          className="px-3 py-1.5 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm text-slate-700 dark:text-slate-300 outline-none focus:border-primary-500"
        >
          <option value="Todos">Qualquer Dificuldade</option>
          {DIFFICULTY_LEVELS.map(d => <option key={d} value={d}>{d}</option>)}
        </select>

        <div className="w-px h-6 bg-slate-300 dark:bg-slate-700 mx-2" />

        <button 
          onClick={() => setSortOrder(prev => prev === 'name' ? 'muscle' : 'name')}
          className="px-3 py-1.5 bg-transparent text-slate-500 hover:text-primary-500 text-xs font-medium uppercase tracking-wide transition-colors"
        >
          Ordenar por: <span className="text-slate-800 dark:text-white font-bold">{sortOrder === 'name' ? 'Nome' : 'Grupo Muscular'}</span>
        </button>
      </div>

      {/* Main List - Hybrid Table/Card Layout */}
      <div className="glass-panel border border-slate-200 dark:border-slate-800 rounded-2xl overflow-hidden">
        {/* Table Header - Adjusted Grid for New Columns */}
        {/* 
            Grid Cols Total: 12
            ID: 1 (Hidden sm)
            Img: 1
            Details: 3
            Muscle Group: 2 (Hidden sm)
            Rating: 2 (Hidden md)
            Video: 1 (Hidden lg)
            Actions: 2
        */}
        <div className="grid grid-cols-12 gap-4 px-6 py-4 bg-slate-50/80 dark:bg-slate-900/50 border-b border-slate-200 dark:border-slate-800 text-xs font-semibold text-slate-400 uppercase tracking-wider">
          <div className="col-span-1 hidden md:block text-center">ID</div>
          <div className="col-span-2 sm:col-span-1 text-center">Img</div>
          <div className="col-span-6 sm:col-span-4 md:col-span-3">Detalhes do Exercício</div>
          <div className="col-span-2 hidden sm:block">Grupo Muscular</div>
          <div className="col-span-2 hidden lg:block">Classificação</div>
          <div className="col-span-1 hidden xl:block">Vídeo</div>
          <div className="col-span-4 sm:col-span-3 md:col-span-2 lg:col-span-2 text-right">Ações</div>
        </div>

        {/* List Items */}
        <div className="divide-y divide-slate-100 dark:divide-slate-800 bg-white/50 dark:bg-slate-900/30">
          {filteredExercises.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-20 text-center">
              <div className="w-20 h-20 bg-slate-100 dark:bg-slate-800 rounded-full flex items-center justify-center mb-4">
                 <Dumbbell size={32} className="text-slate-400" />
              </div>
              <h3 className="text-lg font-bold text-slate-700 dark:text-slate-300">Sem exercícios encontrados</h3>
              <p className="text-slate-500 max-w-xs mt-2 text-sm">Tente ajustar os filtros ou adicione um novo exercício à sua biblioteca.</p>
              <button onClick={handleAdd} className="mt-6 text-primary-600 font-medium hover:underline text-sm">Criar novo exercício</button>
            </div>
          ) : (
            filteredExercises.map((exercise) => (
              <div 
                key={exercise.id} 
                className={`
                  group grid grid-cols-12 gap-4 px-6 py-4 items-center transition-all duration-200 hover:bg-slate-50 dark:hover:bg-slate-800/50
                  ${exercise.isDeleted ? 'opacity-60 grayscale' : ''}
                `}
              >
                {/* ID */}
                <div className="col-span-1 hidden md:block text-center">
                  <span className="text-xs font-mono text-slate-400">#{exercise.id}</span>
                </div>

                {/* Image */}
                <div className="col-span-2 sm:col-span-1 flex justify-center">
                  <div className="w-12 h-12 rounded-xl bg-slate-200 dark:bg-slate-700 overflow-hidden shadow-sm ring-2 ring-white dark:ring-slate-800 relative group-hover:scale-110 transition-transform">
                    <img src={exercise.image} alt={exercise.name} className="w-full h-full object-cover" />
                  </div>
                </div>

                {/* Name & Details (Muscle duplicated here as per request) */}
                <div className="col-span-6 sm:col-span-4 md:col-span-3">
                  <h3 className="font-bold text-slate-800 dark:text-white text-sm sm:text-base truncate pr-2" title={exercise.name}>
                    {exercise.name}
                  </h3>
                  <div className="flex flex-wrap items-center gap-2 mt-1">
                    <span className="text-xs text-slate-500 dark:text-slate-400 font-medium">{exercise.muscleGroup}</span>
                    <span className="hidden sm:inline w-1 h-1 rounded-full bg-slate-300 dark:bg-slate-600"></span>
                    <span className="text-[10px] text-slate-400 uppercase">{exercise.equipment}</span>
                  </div>
                </div>

                {/* Muscle Group (Dedicated Column) */}
                <div className="col-span-2 hidden sm:flex items-center">
                    <span className="px-2.5 py-1 rounded-lg bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 text-xs font-medium border border-slate-200 dark:border-slate-700">
                        {exercise.muscleGroup}
                    </span>
                </div>

                {/* Tags / Rating */}
                <div className="col-span-2 hidden lg:flex flex-col items-start justify-center gap-1.5">
                  <span className={`px-2.5 py-0.5 rounded-full text-[10px] font-bold uppercase tracking-wide ${getDifficultyColor(exercise.difficulty)}`}>
                    {exercise.difficulty}
                  </span>
                  <span className="text-[10px] text-slate-400 line-clamp-1">{exercise.description}</span>
                </div>

                {/* Video Link */}
                <div className="col-span-1 hidden xl:block">
                  {exercise.videos && exercise.videos.length > 0 ? (
                    <div className="flex gap-1">
                        {exercise.videos.slice(0, 2).map((vid, idx) => (
                             <a 
                                key={idx}
                                href={vid.type === 'link' ? vid.url : '#'} 
                                target="_blank" 
                                rel="noreferrer"
                                className="inline-flex items-center justify-center w-8 h-8 text-slate-500 hover:text-primary-500 transition-colors rounded-lg hover:bg-primary-50 dark:hover:bg-primary-900/10"
                                title={`Ver Vídeo ${idx + 1}`}
                            >
                                <PlayCircle size={18} />
                            </a>
                        ))}
                    </div>
                  ) : (
                    <span className="text-xs text-slate-400 italic">--</span>
                  )}
                </div>

                {/* Actions */}
                <div className="col-span-4 sm:col-span-3 md:col-span-2 lg:col-span-2 flex justify-end items-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                   {exercise.isDeleted ? (
                     <>
                        <button 
                          onClick={() => toggleDelete(exercise.id)}
                          title="Restaurar"
                          className="p-2 text-emerald-600 hover:bg-emerald-50 rounded-lg transition-colors"
                        >
                          <RotateCcw size={18} />
                        </button>
                        <button 
                          onClick={() => handleDeletePermanent(exercise.id)}
                          title="Eliminar Permanentemente"
                          className="p-2 text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                        >
                          <Trash2 size={18} />
                        </button>
                     </>
                   ) : (
                     <>
                        <button 
                          onClick={() => handleEdit(exercise)}
                          className="p-2 text-slate-500 hover:text-primary-600 hover:bg-primary-50 dark:hover:bg-primary-900/20 rounded-lg transition-colors"
                        >
                          <Edit2 size={18} />
                        </button>
                        <button 
                          onClick={() => toggleDelete(exercise.id)}
                          className="p-2 text-slate-500 hover:text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition-colors"
                        >
                          <Trash2 size={18} />
                        </button>
                     </>
                   )}
                </div>
              </div>
            ))
          )}
        </div>

        {/* Footer / Pagination */}
        <div className="px-6 py-4 border-t border-slate-200 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-900/50 flex justify-between items-center">
          <p className="text-xs text-slate-500 dark:text-slate-400">
            A mostrar {filteredExercises.length} resultados
          </p>
          <div className="flex gap-2">
            <button disabled className="px-3 py-1 text-xs font-medium rounded-lg border border-slate-200 dark:border-slate-700 text-slate-400 cursor-not-allowed">Anterior</button>
            <button className="px-3 py-1 text-xs font-medium rounded-lg bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-300 hover:border-primary-500 hover:text-primary-500 transition-colors">1</button>
            <button className="px-3 py-1 text-xs font-medium rounded-lg bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-slate-700">2</button>
            <button className="px-3 py-1 text-xs font-medium rounded-lg bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-slate-700">Seguinte</button>
          </div>
        </div>
      </div>

      {/* Modal */}
      <ExerciseModal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        onSave={handleSave}
        initialData={editingExercise}
      />
    </div>
  );
};

export default ExercisesView;

export type Status = 'active' | 'pending' | 'inactive' | 'completed' | 'warning';

export interface Client {
  id: string;
  name: string;
  avatar: string;
  plan: string;
  status: Status;
  lastActive: string;
  contact: string;
  progress: number;
}

export interface DashboardEvent {
  id: string;
  type: 'birthday' | 'check-in' | 'goal' | 'payment';
  clientId: string;
  clientName: string;
  title: string;
  time: string;
  isUrgent?: boolean;
}

export interface PendingItem {
  id: string;
  type: 'workout_submission' | 'physical_assessment' | 'nutrition_update';
  clientId: string;
  clientName: string;
  date: string;
  status: Status;
  details: string;
}

export interface Feedback {
  id: string;
  clientId: string;
  clientName: string;
  avatar: string;
  rating: number; // 1-5
  comment: string;
  date: string;
  read: boolean;
}

export interface Metric {
  label: string;
  value: string;
  trend: number; // percentage
  trendLabel: string;
}

export type VideoType = 'link' | 'upload';

export interface ExerciseVideo {
  type: VideoType;
  url: string; // URL for link or object URL/filename for upload
}

export interface Exercise {
  id: string;
  name: string;
  image: string;
  muscleGroup: string;
  type: 'Indefinido' | 'Alongamento' | 'Mobilidade' | 'Força';
  equipment: string; // 'Peso Livre', 'Máquina', 'Peso Corporal', 'Cabo'
  difficulty: 'Iniciante' | 'Intermédio' | 'Avançado';
  videos: ExerciseVideo[];
  description: string;
  notes?: string;
  isDeleted: boolean;
}

export type FoodCategory = 'Proteína' | 'Hidratos' | 'Gordura' | 'Vegetais' | 'Fruta' | 'Laticínios' | 'Suplementos' | 'Bebidas' | 'Outros';
export type FoodUnit = 'g' | 'ml' | 'unidade';

export interface Food {
  id: string;
  name: string;
  image: string;
  category: FoodCategory;
  unit: FoodUnit;
  baseQuantity: number; // e.g. 100g or 1 unit
  calories: number;
  protein: number;
  carbs: number;
  fat: number;
  fiber?: number;
  sugar?: number;
  sodium?: number;
  description?: string;
  isDeleted: boolean;
}

import React, { useState, useEffect } from 'react';
import { X, Upload, Save, AlertCircle, FileText } from 'lucide-react';
import { Food, FoodCategory, FoodUnit } from '../../types';
import { FOOD_CATEGORIES, FOOD_UNITS } from '../../constants';

interface FoodModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (food: Omit<Food, 'id' | 'isDeleted'>) => void;
  initialData?: Food | null;
}

const FoodModal: React.FC<FoodModalProps> = ({ isOpen, onClose, onSave, initialData }) => {
  const [formData, setFormData] = useState<{
    name: string;
    image: string;
    category: FoodCategory;
    unit: FoodUnit;
    baseQuantity: number;
    calories: number;
    protein: number;
    carbs: number;
    fat: number;
    fiber: number;
    sodium: number;
    sugar: number;
    description: string;
  }>({
    name: '',
    image: '',
    category: 'Proteína',
    unit: 'g',
    baseQuantity: 100,
    calories: 0,
    protein: 0,
    carbs: 0,
    fat: 0,
    fiber: 0,
    sodium: 0,
    sugar: 0,
    description: ''
  });

  useEffect(() => {
    if (initialData) {
      setFormData({
        name: initialData.name,
        image: initialData.image,
        category: initialData.category,
        unit: initialData.unit,
        baseQuantity: initialData.baseQuantity,
        calories: initialData.calories,
        protein: initialData.protein,
        carbs: initialData.carbs,
        fat: initialData.fat,
        fiber: initialData.fiber || 0,
        sodium: initialData.sodium || 0,
        sugar: initialData.sugar || 0,
        description: initialData.description || ''
      });
    } else {
      setFormData({
        name: '',
        image: '',
        category: 'Proteína',
        unit: 'g',
        baseQuantity: 100,
        calories: 0,
        protein: 0,
        carbs: 0,
        fat: 0,
        fiber: 0,
        sodium: 0,
        sugar: 0,
        description: ''
      });
    }
  }, [initialData, isOpen]);

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave({
      ...formData,
      image: formData.image || 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&q=80&w=200&h=200' // Default healthy food image
    });
    onClose();
  };

  const handleNumericChange = (field: string, value: string) => {
    const numValue = parseFloat(value);
    setFormData(prev => ({
      ...prev,
      [field]: isNaN(numValue) ? 0 : numValue
    }));
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 sm:p-6">
      <div 
        className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm transition-opacity" 
        onClick={onClose}
      />

      <div className="relative w-full max-w-3xl bg-white dark:bg-slate-900 rounded-2xl shadow-2xl ring-1 ring-slate-200 dark:ring-slate-800 flex flex-col max-h-[90vh] overflow-hidden animate-fade-in-up">

        {/* Header */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-slate-100 dark:border-slate-800 bg-white dark:bg-slate-900 z-10">
          <div>
            <h2 className="text-xl font-bold text-slate-900 dark:text-white">
              {initialData ? 'Editar Alimento' : 'Novo Alimento'}
            </h2>
            <p className="text-xs text-slate-500 dark:text-slate-400">Registe a informação nutricional detalhada.</p>
          </div>
          <button 
            onClick={onClose}
            className="p-2 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg transition-colors"
          >
            <X size={20} />
          </button>
        </div>

        {/* Form Body */}
        <div className="flex-1 overflow-y-auto p-6 custom-scrollbar bg-slate-50/50 dark:bg-slate-900/50">
          <form id="food-form" onSubmit={handleSubmit} className="space-y-6">

            <div className="grid grid-cols-12 gap-6">

              {/* Image & Basic Info */}
              <div className="col-span-12 md:col-span-4 space-y-4">
                {/* Image Upload */}
                <div>
                   <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">Imagem</label>
                   <div className="aspect-square rounded-xl bg-slate-100 dark:bg-slate-800 border-2 border-dashed border-slate-300 dark:border-slate-700 flex flex-col items-center justify-center overflow-hidden group hover:border-primary-500 transition-colors relative">
                       {formData.image ? (
                         <img src={formData.image} alt="Preview" className="w-full h-full object-cover absolute inset-0" />
                       ) : (
                         <div className="text-center p-4">
                            <Upload size={24} className="mx-auto text-slate-400 group-hover:text-primary-500 transition-colors mb-2" />
                            <span className="text-xs text-slate-400">URL ou Upload</span>
                         </div>
                       )}
                   </div>
                   <input 
                      type="text" 
                      placeholder="URL da imagem..." 
                      value={formData.image}
                      onChange={(e) => setFormData({...formData, image: e.target.value})}
                      className="mt-2 w-full px-3 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-xs focus:ring-2 focus:ring-primary-500 outline-none transition-all"
                    />
                </div>
              </div>

              {/* Main Info */}
              <div className="col-span-12 md:col-span-8 space-y-4">
                 <div>
                  <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Nome do Alimento</label>
                  <input 
                    required
                    type="text" 
                    value={formData.name}
                    onChange={(e) => setFormData({...formData, name: e.target.value})}
                    className="w-full px-4 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm focus:ring-2 focus:ring-primary-500 outline-none transition-all"
                    placeholder="Ex: Peito de Frango, Arroz Basmati..."
                  />
                </div>

                <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Categoria</label>
                      <select 
                        value={formData.category}
                        onChange={(e) => setFormData({...formData, category: e.target.value as FoodCategory})}
                        className="w-full px-4 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm focus:ring-2 focus:ring-primary-500 outline-none transition-all"
                      >
                        {FOOD_CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                      </select>
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Unidade de Medida</label>
                      <select 
                        value={formData.unit}
                        onChange={(e) => setFormData({...formData, unit: e.target.value as FoodUnit})}
                        className="w-full px-4 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm focus:ring-2 focus:ring-primary-500 outline-none transition-all"
                      >
                        {FOOD_UNITS.map(u => <option key={u} value={u}>{u}</option>)}
                      </select>
                    </div>
                </div>

                <div>
                   <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Quantidade Base (para cálculo)</label>
                   <div className="relative">
                      <input 
                        type="number" 
                        value={formData.baseQuantity}
                        onChange={(e) => handleNumericChange('baseQuantity', e.target.value)}
                        className="w-full px-4 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm focus:ring-2 focus:ring-primary-500 outline-none transition-all"
                      />
                      <span className="absolute right-4 top-1/2 -translate-y-1/2 text-xs font-semibold text-slate-400">{formData.unit}</span>
                   </div>
                </div>
              </div>

              {/* Macros Section */}
              <div className="col-span-12">
                 <h3 className="text-sm font-bold text-slate-900 dark:text-white mb-3 flex items-center gap-2">
                    <Activity size={16} className="text-primary-500" />
                    Informação Nutricional <span className="text-xs font-normal text-slate-400">(por {formData.baseQuantity}{formData.unit})</span>
                 </h3>

                 <div className="p-4 bg-white dark:bg-slate-800 rounded-xl border border-slate-200 dark:border-slate-700 shadow-sm">
                    {/* Primary Macros */}
                    <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 mb-6">
                        <div className="p-3 rounded-lg bg-slate-50 dark:bg-slate-900/50 border border-slate-100 dark:border-slate-700/50 text-center">
                            <label className="text-xs font-semibold text-slate-500 uppercase tracking-wider block mb-1">Calorias</label>
                            <input 
                              type="number" 
                              value={formData.calories}
                              onChange={(e) => handleNumericChange('calories', e.target.value)}
                              className="w-full text-center bg-transparent text-xl font-bold text-slate-800 dark:text-white border-b border-slate-200 focus:border-primary-500 outline-none p-0"
                            />
                            <span className="text-[10px] text-slate-400">kcal</span>
                        </div>
                        <div className="p-3 rounded-lg bg-blue-50 dark:bg-blue-900/10 border border-blue-100 dark:border-blue-900/20 text-center">
                            <label className="text-xs font-semibold text-blue-600 dark:text-blue-400 uppercase tracking-wider block mb-1">Proteína</label>
                            <input 
                              type="number" 
                              value={formData.protein}
                              onChange={(e) => handleNumericChange('protein', e.target.value)}
                              className="w-full text-center bg-transparent text-xl font-bold text-blue-700 dark:text-blue-300 border-b border-blue-200 focus:border-blue-500 outline-none p-0"
                            />
                            <span className="text-[10px] text-blue-400">gramas</span>
                        </div>
                        <div className="p-3 rounded-lg bg-amber-50 dark:bg-amber-900/10 border border-amber-100 dark:border-amber-900/20 text-center">
                            <label className="text-xs font-semibold text-amber-600 dark:text-amber-400 uppercase tracking-wider block mb-1">Hidratos</label>
                            <input 
                              type="number" 
                              value={formData.carbs}
                              onChange={(e) => handleNumericChange('carbs', e.target.value)}
                              className="w-full text-center bg-transparent text-xl font-bold text-amber-700 dark:text-amber-300 border-b border-amber-200 focus:border-amber-500 outline-none p-0"
                            />
                            <span className="text-[10px] text-amber-400">gramas</span>
                        </div>
                        <div className="p-3 rounded-lg bg-rose-50 dark:bg-rose-900/10 border border-rose-100 dark:border-rose-900/20 text-center">
                            <label className="text-xs font-semibold text-rose-600 dark:text-rose-400 uppercase tracking-wider block mb-1">Gordura</label>
                            <input 
                              type="number" 
                              value={formData.fat}
                              onChange={(e) => handleNumericChange('fat', e.target.value)}
                              className="w-full text-center bg-transparent text-xl font-bold text-rose-700 dark:text-rose-300 border-b border-rose-200 focus:border-rose-500 outline-none p-0"
                            />
                            <span className="text-[10px] text-rose-400">gramas</span>
                        </div>
                    </div>

                    {/* Secondary Macros */}
                    <div className="grid grid-cols-3 gap-4 pt-4 border-t border-slate-100 dark:border-slate-700">
                        <div className="text-center">
                           <label className="block text-xs text-slate-500 mb-1">Fibra (g)</label>
                           <input 
                              type="number" 
                              value={formData.fiber}
                              onChange={(e) => handleNumericChange('fiber', e.target.value)}
                              className="w-full text-center text-sm font-semibold bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-lg py-1.5 focus:ring-1 focus:ring-slate-400 outline-none" 
                           />
                        </div>
                        <div className="text-center">
                           <label className="block text-xs text-slate-500 mb-1">Sódio (mg)</label>
                           <input 
                              type="number" 
                              value={formData.sodium}
                              onChange={(e) => handleNumericChange('sodium', e.target.value)}
                              className="w-full text-center text-sm font-semibold bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-lg py-1.5 focus:ring-1 focus:ring-slate-400 outline-none" 
                           />
                        </div>
                        <div className="text-center">
                           <label className="block text-xs text-slate-500 mb-1">Açúcar (g)</label>
                           <input 
                              type="number" 
                              value={formData.sugar}
                              onChange={(e) => handleNumericChange('sugar', e.target.value)}
                              className="w-full text-center text-sm font-semibold bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-lg py-1.5 focus:ring-1 focus:ring-slate-400 outline-none" 
                           />
                        </div>
                    </div>
                 </div>
              </div>

              {/* Description */}
              <div className="col-span-12">
                 <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">Descrição / Notas</label>
                 <div className="relative">
                   <FileText size={16} className="absolute left-3 top-3 text-slate-400 pointer-events-none" />
                   <textarea 
                     rows={3}
                     value={formData.description}
                     onChange={(e) => setFormData({...formData, description: e.target.value})}
                     className="w-full pl-9 pr-4 py-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm focus:ring-2 focus:ring-primary-500 outline-none transition-all resize-none"
                     placeholder="Detalhes adicionais sobre o alimento, marcas recomendadas, etc..."
                   />
                 </div>
              </div>

            </div>
          </form>
        </div>

        {/* Footer */}
        <div className="px-6 py-4 bg-white dark:bg-slate-900 border-t border-slate-100 dark:border-slate-800 flex justify-end gap-3 z-10">
          <button 
            type="button" 
            onClick={onClose}
            className="px-4 py-2 text-sm font-medium text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg transition-colors"
          >
            Cancelar
          </button>
          <button 
            form="food-form"
            type="submit"
            className="flex items-center gap-2 px-6 py-2 text-sm font-medium text-white bg-primary-600 hover:bg-primary-500 active:bg-primary-700 rounded-lg shadow-lg shadow-primary-500/20 transition-all transform hover:-translate-y-0.5"
          >
            <Save size={18} />
            Guardar Alimento
          </button>
        </div>

      </div>
    </div>
  );
};

export default FoodModal;

import React, { useState, useMemo } from 'react';
import { 
  Search, 
  Plus, 
  Filter, 
  Trash2, 
  Edit2, 
  RotateCcw, 
  Utensils,
  ChevronDown,
  ChevronUp
} from 'lucide-react';
import { Food, FoodCategory } from '../../types';
import { MOCK_FOODS, FOOD_CATEGORIES, FOOD_UNITS } from '../../constants';
import FoodModal from './FoodModal';

const FoodView: React.FC = () => {
  // State
  const [foods, setFoods] = useState<Food[]>(MOCK_FOODS);
  const [searchQuery, setSearchQuery] = useState('');
  const [showDeleted, setShowDeleted] = useState(false);

  // Filter States
  const [showAdvancedFilters, setShowAdvancedFilters] = useState(false);
  const [filterCategory, setFilterCategory] = useState<string>('Todos');
  const [filterUnit, setFilterUnit] = useState<string>('Todos');
  const [minProtein, setMinProtein] = useState<string>('');

  // Sort State
  const [sortConfig, setSortConfig] = useState<{ key: keyof Food, direction: 'asc' | 'desc' } | null>(null);

  // Modal State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingFood, setEditingFood] = useState<Food | null>(null);

  // Handlers
  const handleAdd = () => {
    setEditingFood(null);
    setIsModalOpen(true);
  };

  const handleEdit = (food: Food) => {
    setEditingFood(food);
    setIsModalOpen(true);
  };

  const handleSave = (foodData: Omit<Food, 'id' | 'isDeleted'>) => {
    if (editingFood) {
      // Update existing
      setFoods(prev => prev.map(item => 
        item.id === editingFood.id ? { ...item, ...foodData } : item
      ));
    } else {
      // Create new
      const newFood: Food = {
        ...foodData,
        id: Math.random().toString(36).substr(2, 9),
        isDeleted: false
      };
      setFoods(prev => [newFood, ...prev]);
    }
  };

  const toggleDelete = (id: string) => {
    setFoods(prev => prev.map(item => {
      if (item.id === id) {
        return { ...item, isDeleted: !item.isDeleted };
      }
      return item;
    }));
  };

  const handleDeletePermanent = (id: string) => {
    if (confirm('Tem a certeza que deseja eliminar permanentemente este alimento?')) {
      setFoods(prev => prev.filter(item => item.id !== id));
    }
  };

  const handleSort = (key: keyof Food) => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  // Filter & Sort Logic
  const filteredFoods = useMemo(() => {
    let result = foods.filter(item => {
        if (!showDeleted && item.isDeleted) return false;
        if (showDeleted && !item.isDeleted) return false;

        const matchesSearch = item.name.toLowerCase().includes(searchQuery.toLowerCase());
        const matchesCategory = filterCategory === 'Todos' || item.category === filterCategory;
        const matchesUnit = filterUnit === 'Todos' || item.unit === filterUnit;
        const matchesProtein = minProtein === '' || item.protein >= parseFloat(minProtein);

        return matchesSearch && matchesCategory && matchesUnit && matchesProtein;
    });

    if (sortConfig) {
      result.sort((a, b) => {
        // @ts-ignore - dynamic sorting
        const valA = a[sortConfig.key];
        // @ts-ignore
        const valB = b[sortConfig.key];

        if (valA < valB) return sortConfig.direction === 'asc' ? -1 : 1;
        if (valA > valB) return sortConfig.direction === 'asc' ? 1 : -1;
        return 0;
      });
    }

    return result;
  }, [foods, searchQuery, showDeleted, filterCategory, filterUnit, minProtein, sortConfig]);

  // Visual Helper: Get Category Color
  const getCategoryColor = (cat: string) => {
      switch(cat) {
          case 'Proteína': return 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400 border-blue-200 dark:border-blue-800';
          case 'Hidratos': return 'bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400 border-amber-200 dark:border-amber-800';
          case 'Gordura': return 'bg-rose-100 text-rose-700 dark:bg-rose-900/30 dark:text-rose-400 border-rose-200 dark:border-rose-800';
          case 'Vegetais': return 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400 border-emerald-200 dark:border-emerald-800';
          case 'Fruta': return 'bg-pink-100 text-pink-700 dark:bg-pink-900/30 dark:text-pink-400 border-pink-200 dark:border-pink-800';
          default: return 'bg-slate-100 text-slate-700 dark:bg-slate-800 dark:text-slate-300 border-slate-200 dark:border-slate-700';
      }
  };

  return (
    <div className="space-y-6 animate-fade-in pb-20">

      {/* Top Toolbar */}
      <div className="glass-card rounded-2xl p-4 flex flex-col gap-4 sticky top-0 z-20">
         <div className="flex flex-col md:flex-row justify-between items-center gap-4">
            {/* Left: Search & Toggles */}
            <div className="flex flex-col sm:flex-row gap-3 w-full md:w-auto">
                <div className="relative group min-w-[280px]">
                    <Search size={18} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-primary-500 transition-colors" />
                    <input 
                    type="text" 
                    placeholder="Pesquisar alimentos..." 
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    className="w-full pl-10 pr-4 py-2.5 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-primary-500 outline-none transition-all text-sm"
                    />
                </div>

                <button 
                    onClick={() => setShowAdvancedFilters(!showAdvancedFilters)}
                    className={`
                    flex items-center justify-center px-4 py-2.5 rounded-xl border text-sm font-medium transition-all
                    ${showAdvancedFilters
                        ? 'bg-primary-50 border-primary-200 text-primary-600 dark:bg-primary-900/20 dark:border-primary-800 dark:text-primary-400' 
                        : 'bg-white border-slate-200 text-slate-600 dark:bg-slate-800/50 dark:border-slate-700 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-slate-800'}
                    `}
                >
                    <Filter size={16} className="mr-2" />
                    Filtros {showAdvancedFilters ? <ChevronUp size={14} className="ml-1"/> : <ChevronDown size={14} className="ml-1"/>}
                </button>
            </div>

            {/* Right: Actions */}
            <div className="flex gap-3 w-full md:w-auto justify-end">
                <button 
                    onClick={() => setShowDeleted(!showDeleted)}
                    className={`
                    flex items-center px-4 py-2.5 rounded-xl border text-sm font-medium transition-all
                    ${showDeleted 
                        ? 'bg-amber-50 border-amber-200 text-amber-600 dark:bg-amber-900/20 dark:border-amber-800 dark:text-amber-400' 
                        : 'bg-white border-slate-200 text-slate-500 hover:text-slate-700 dark:bg-slate-800/50 dark:border-slate-700 dark:text-slate-400'}
                    `}
                >
                    <Trash2 size={16} />
                </button>

                <button 
                    onClick={handleAdd}
                    className="flex items-center px-5 py-2.5 bg-gradient-to-r from-primary-600 to-primary-500 text-white rounded-xl font-bold text-sm shadow-lg shadow-primary-500/25 hover:shadow-primary-500/40 hover:-translate-y-0.5 active:translate-y-0 transition-all"
                >
                    <Plus size={18} className="mr-2" />
                    Adicionar Alimento
                </button>
            </div>
         </div>

         {/* Advanced Filters Panel */}
         {showAdvancedFilters && (
             <div className="pt-2 border-t border-slate-100 dark:border-slate-800 grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 animate-fade-in-down">
                <div>
                   <label className="block text-xs font-semibold text-slate-500 dark:text-slate-400 mb-1">Categoria</label>
