import { FOOD_CATEGORIES, FOOD_UNITS } from '../../constants';

interface FoodModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (food: Omit<Food, 'id' | 'isDeleted'>) => void;
  initialData?: Food | null;
}

const FoodModal: React.FC<FoodModalProps> = ({ isOpen, onClose, onSave, initialData }) => {
  const [formData, setFormData] = useState<{
    name: string;
    image: string;
    category: FoodCategory;
    unit: FoodUnit;
    baseQuantity: number;
    calories: number;
    protein: number;
    carbs: number;
    fat: number;
    fiber: number;
    sodium: number;
    sugar: number;
    description: string;
  }>({
    name: '',
    image: '',
    category: 'Proteína',
    unit: 'g',
    baseQuantity: 100,
    calories: 0,
    protein: 0,
    carbs: 0,
    fat: 0,
    fiber: 0,
    sodium: 0,
    sugar: 0,
    description: ''
  });

  useEffect(() => {
    if (initialData) {
      setFormData({
        name: initialData.name,
        image: initialData.image,
        category: initialData.category,
        unit: initialData.unit,
        baseQuantity: initialData.baseQuantity,
        calories: initialData.calories,
        protein: initialData.protein,
        carbs: initialData.carbs,
        fat: initialData.fat,
        fiber: initialData.fiber || 0,
        sodium: initialData.sodium || 0,
        sugar: initialData.sugar || 0,
        description: initialData.description || ''
      });
    } else {
      setFormData({
        name: '',
        image: '',
        category: 'Proteína',
        unit: 'g',
        baseQuantity: 100,
        calories: 0,
        protein: 0,
        carbs: 0,
        fat: 0,
        fiber: 0,
        sodium: 0,
        sugar: 0,
        description: ''
      });
    }
  }, [initialData, isOpen]);

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave({
      ...formData,
      image: formData.image || 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&q=80&w=200&h=200' // Default healthy food image
    });
    onClose();
  };

  const handleNumericChange = (field: string, value: string) => {
    const numValue = parseFloat(value);
    setFormData(prev => ({
      ...prev,
      [field]: isNaN(numValue) ? 0 : numValue
    }));
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 sm:p-6">
