import React, { useState, useEffect } from 'react';
import { X, Upload, Save, Link as LinkIcon, FileText, Layout, Video, BookOpen, File as FileIcon, Mic } from 'lucide-react';
import { ContentItem, ContentType, ContentCategory } from '../../types';
import { CONTENT_TYPES, CONTENT_CATEGORIES } from '../../constants';

interface ContentModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (content: Omit<ContentItem, 'id' | 'isDeleted' | 'createdAt'>) => void;
  initialData?: ContentItem | null;
}

const ContentModal: React.FC<ContentModalProps> = ({ isOpen, onClose, onSave, initialData }) => {
  const [formData, setFormData] = useState<{
    title: string;
    thumbnail: string;
    type: ContentType;
    category: ContentCategory;
    description: string;
    url: string;
  }>({
    title: '',
    thumbnail: '',
    type: 'video',
    category: 'Treino',
    description: '',
    url: ''
  });

  useEffect(() => {
    if (initialData) {
      setFormData({
        title: initialData.title,
        thumbnail: initialData.thumbnail,
        type: initialData.type,
        category: initialData.category,
        description: initialData.description,
        url: initialData.url
      });
    } else {
      setFormData({
        title: '',
        thumbnail: '',
        type: 'video',
        category: 'Treino',
        description: '',
        url: ''
      });
    }
  }, [initialData, isOpen]);

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave({
      ...formData,
      thumbnail: formData.thumbnail || 'https://images.unsplash.com/photo-1557804506-669a67965ba0?auto=format&fit=crop&q=80&w=600&h=400' // Fallback image
    });
    onClose();
  };

  const getTypeIcon = (type: ContentType) => {
    switch (type) {
      case 'video': return <Video size={16} />;
      case 'article': return <BookOpen size={16} />;
      case 'pdf': return <FileIcon size={16} />;
      case 'audio': return <Mic size={16} />;
      default: return <LinkIcon size={16} />;
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 sm:p-6">
      <div 
        className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm transition-opacity" 
        onClick={onClose}
      />

      <div className="relative w-full max-w-3xl bg-white dark:bg-slate-900 rounded-2xl shadow-2xl ring-1 ring-slate-200 dark:ring-slate-800 flex flex-col max-h-[90vh] overflow-hidden animate-fade-in-up">

        {/* Header */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-slate-100 dark:border-slate-800 bg-white dark:bg-slate-900 z-10">
          <div>
            <h2 className="text-xl font-bold text-slate-900 dark:text-white">
              {initialData ? 'Editar Conteúdo' : 'Novo Conteúdo'}
            </h2>
            <p className="text-xs text-slate-500 dark:text-slate-400">Adicione vídeos, guias ou artigos à sua biblioteca.</p>
          </div>
          <button 
            onClick={onClose}
            className="p-2 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg transition-colors"
          >
            <X size={20} />
          </button>
        </div>

        {/* Form Body */}
        <div className="flex-1 overflow-y-auto p-6 custom-scrollbar bg-slate-50/50 dark:bg-slate-900/50">
          <form id="content-form" onSubmit={handleSubmit} className="space-y-6">

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">

              {/* Thumbnail Section */}
              <div className="col-span-1 md:col-span-2">
                 <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-3">Thumbnail / Capa</label>
                 <div className="flex flex-col sm:flex-row gap-4">
                    <div className="w-full sm:w-48 aspect-video rounded-xl bg-slate-100 dark:bg-slate-900 border-2 border-dashed border-slate-300 dark:border-slate-700 flex items-center justify-center shrink-0 overflow-hidden group hover:border-primary-500 transition-colors relative">
                       {formData.thumbnail ? (
                         <img src={formData.thumbnail} alt="Preview" className="w-full h-full object-cover" />
                       ) : (
                         <div className="flex flex-col items-center justify-center text-slate-400">
                           <Upload size={24} className="mb-2 group-hover:text-primary-500 transition-colors" />
                           <span className="text-xs">Preview</span>
                         </div>
                       )}
                    </div>
                    <div className="flex-1 flex flex-col justify-center">
                      <label className="text-xs text-slate-500 mb-1.5 ml-1">URL da Imagem</label>
                      <input 
                        type="text" 
                        placeholder="https://..." 
                        value={formData.thumbnail}
                        onChange={(e) => setFormData({...formData, thumbnail: e.target.value})}
                        className="w-full px-3 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm focus:ring-2 focus:ring-primary-500 outline-none transition-all mb-2"
                      />
                      <p className="text-xs text-slate-400">Recomendado: 16:9 ratio. Deixe vazio para usar imagem padrão.</p>
                    </div>
                 </div>
              </div>

              {/* Title */}
              <div className="col-span-1 md:col-span-2">
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Título do Conteúdo</label>
                <div className="relative">
                  <Layout size={16} className="absolute left-3 top-3 text-slate-400 pointer-events-none" />
                  <input 
                    required
                    type="text" 
                    value={formData.title}
                    onChange={(e) => setFormData({...formData, title: e.target.value})}
                    className="w-full pl-9 pr-4 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm focus:ring-2 focus:ring-primary-500 outline-none transition-all font-medium"
                    placeholder="Ex: Guia Completo de Hipertrofia"
                  />
                </div>
              </div>

              {/* Type & Category */}
              <div>
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Tipo de Conteúdo</label>
                <div className="grid grid-cols-2 gap-2">
                   {CONTENT_TYPES.map(type => (
                      <button
                        key={type}
                        type="button"
                        onClick={() => setFormData({...formData, type})}
                        className={`flex items-center justify-center gap-2 px-3 py-2 rounded-lg text-xs font-medium border transition-all ${
                            formData.type === type 
                            ? 'bg-primary-50 dark:bg-primary-900/20 border-primary-200 dark:border-primary-800 text-primary-700 dark:text-primary-300' 
                            : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-500 hover:bg-slate-50 dark:hover:bg-slate-700'
                        }`}
                      >
                         {getTypeIcon(type)}
                         <span className="capitalize">{type}</span>
                      </button>
                   ))}
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Categoria</label>
                <select 
                  value={formData.category}
                  onChange={(e) => setFormData({...formData, category: e.target.value as ContentCategory})}
                  className="w-full px-4 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm focus:ring-2 focus:ring-primary-500 outline-none transition-all"
                >
                  {CONTENT_CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                </select>
              </div>

              {/* URL */}
              <div className="col-span-1 md:col-span-2">
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Link do Recurso (URL)</label>
                <div className="relative">
                  <LinkIcon size={16} className="absolute left-3 top-3 text-slate-400 pointer-events-none" />
                  <input 
                    required
                    type="url" 
                    value={formData.url}
                    onChange={(e) => setFormData({...formData, url: e.target.value})}
                    className="w-full pl-9 pr-4 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm focus:ring-2 focus:ring-primary-500 outline-none transition-all font-mono text-xs text-blue-600 dark:text-blue-400"
                    placeholder={formData.type === 'video' ? "https://youtube.com/..." : "https://..."}
                  />
                </div>
              </div>

              {/* Description */}
              <div className="col-span-1 md:col-span-2">
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">Descrição</label>
                <div className="relative">
                   <FileText size={16} className="absolute left-3 top-3 text-slate-400 pointer-events-none" />
                   <textarea 
                     rows={4}
                     value={formData.description}
                     onChange={(e) => setFormData({...formData, description: e.target.value})}
                     className="w-full pl-9 pr-4 py-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm focus:ring-2 focus:ring-primary-500 outline-none transition-all resize-none leading-relaxed"
                     placeholder="Breve resumo do conteúdo..."
                   />
                </div>
              </div>

            </div>
          </form>
        </div>

        {/* Footer */}
        <div className="px-6 py-4 bg-white dark:bg-slate-900 border-t border-slate-100 dark:border-slate-800 flex justify-end gap-3 z-10">
          <button 
            type="button" 
            onClick={onClose}
            className="px-4 py-2 text-sm font-medium text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg transition-colors"
          >
            Cancelar
          </button>
          <button 
            form="content-form"
            type="submit"
            className="flex items-center gap-2 px-6 py-2 text-sm font-medium text-white bg-primary-600 hover:bg-primary-500 active:bg-primary-700 rounded-lg shadow-lg shadow-primary-500/20 transition-all transform hover:-translate-y-0.5"
          >
            <Save size={18} />
            Guardar
          </button>
        </div>

      </div>
    </div>
  );
};

export default ContentModal;

import React from 'react';
import { X, ExternalLink, Calendar, Tag, FileText, Video, PlayCircle } from 'lucide-react';
import { ContentItem } from '../../types';

interface ContentDetailModalProps {
  isOpen: boolean;
  onClose: () => void;
  content: ContentItem | null;
}

const ContentDetailModal: React.FC<ContentDetailModalProps> = ({ isOpen, onClose, content }) => {
  if (!isOpen || !content) return null;

  const isVideo = content.type === 'video';
  const isPDF = content.type === 'pdf';

  // Logic to determine action text
  const getActionText = () => {
    switch(content.type) {
        case 'video': return 'Ver no YouTube';
        case 'pdf': return 'Abrir Documento PDF';
        case 'article': return 'Ler Artigo Completo';
        case 'audio': return 'Ouvir Áudio';
        default: return 'Aceder ao Link';
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 sm:p-6">
      {/* Backdrop */}
      <div 
        className="absolute inset-0 bg-slate-900/80 backdrop-blur-sm transition-opacity" 
        onClick={onClose}
      />

      {/* Modal Content */}
      <div className="relative w-full max-w-4xl bg-white dark:bg-slate-900 rounded-2xl shadow-2xl ring-1 ring-slate-200 dark:ring-slate-800 overflow-hidden animate-fade-in-up flex flex-col max-h-[90vh]">

        {/* Close Button */}
        <button 
            onClick={onClose}
            className="absolute top-4 right-4 z-20 p-2 bg-black/20 hover:bg-black/40 text-white rounded-full transition-colors backdrop-blur-sm"
        >
            <X size={20} />
        </button>

        {/* Media Preview Section */}
        <div className={`w-full bg-slate-900 relative flex items-center justify-center ${isVideo ? 'aspect-video' : 'h-64'}`}>
            {isVideo ? (
                 <iframe 
                    width="100%" 
                    height="100%" 
                    src={content.url} 
                    title={content.title}
                    frameBorder="0" 
                    allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" 
                    allowFullScreen
                    className="w-full h-full"
                 ></iframe>
            ) : (
                <div className="relative w-full h-full">
                    <img 
                        src={content.thumbnail} 
                        alt={content.title} 
                        className="w-full h-full object-cover opacity-60"
                    />
                    <div className="absolute inset-0 bg-gradient-to-t from-slate-900 via-slate-900/40 to-transparent flex flex-col items-center justify-center">
                        {isPDF ? (
                            <FileText size={64} className="text-white/80 mb-4" />
                        ) : (
                             <ExternalLink size={64} className="text-white/80 mb-4" />
                        )}
                        <h2 className="text-2xl md:text-3xl font-bold text-white text-center px-4 drop-shadow-lg">
                            {content.title}
                        </h2>
                    </div>
                </div>
            )}
        </div>

        {/* Info Section */}
        <div className="flex-1 overflow-y-auto p-6 md:p-8 bg-white dark:bg-slate-900">
             <div className="flex flex-wrap items-center gap-3 mb-6">
                 <span className={`px-3 py-1 rounded-full text-xs font-bold uppercase tracking-wider border flex items-center gap-1.5
                    ${content.type === 'video' ? 'bg-red-50 text-red-600 border-red-100 dark:bg-red-900/20 dark:text-red-400 dark:border-red-900/50' : 
                      content.type === 'pdf' ? 'bg-amber-50 text-amber-600 border-amber-100 dark:bg-amber-900/20 dark:text-amber-400 dark:border-amber-900/50' :
                      'bg-blue-50 text-blue-600 border-blue-100 dark:bg-blue-900/20 dark:text-blue-400 dark:border-blue-900/50'
                    }
                 `}>
                    {content.type === 'video' && <Video size={12}/>}
                    {content.type === 'pdf' && <FileText size={12}/>}
                    {content.type}
                 </span>
                 <span className="flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-medium text-slate-600 dark:text-slate-300 bg-slate-100 dark:bg-slate-800">
                    <Tag size={12} /> {content.category}
                 </span>
                 <span className="flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-medium text-slate-500 dark:text-slate-400">
                    <Calendar size={12} /> {content.createdAt}
                 </span>
             </div>

             <div className="prose prose-sm dark:prose-invert max-w-none mb-8">
                 <h3 className="text-lg font-bold text-slate-800 dark:text-white mb-2">Sobre este conteúdo</h3>
                 <p className="text-slate-600 dark:text-slate-300 leading-relaxed">
                     {content.description}
                 </p>
             </div>

             <div className="flex items-center justify-center pt-6 border-t border-slate-100 dark:border-slate-800">
                 {!isVideo && (
                     <a 
                        href={content.url} 
                        target="_blank" 
                        rel="noopener noreferrer"
                        className="flex items-center gap-2 px-8 py-3 bg-primary-600 hover:bg-primary-500 text-white rounded-xl shadow-lg hover:shadow-primary-500/25 transition-all transform hover:-translate-y-0.5 font-semibold"
                     >
                        <ExternalLink size={18} />
                        {getActionText()}
                     </a>
                 )}
                 {isVideo && (
                     <a 
                        href={content.url} 
                        target="_blank" 
                        rel="noopener noreferrer"
                        className="text-slate-500 hover:text-slate-800 dark:hover:text-slate-200 text-sm font-medium flex items-center gap-1 transition-colors"
                     >
                        Abrir no YouTube <ExternalLink size={14} />
                     </a>
                 )}
             </div>
        </div>

      </div>
    </div>
  );
};

export default ContentDetailModal;

import React, { useState, useMemo } from 'react';
import { 
  Search, 
  Plus, 
  Filter, 
  Trash2, 
  Edit2, 
  RotateCcw, 
  FileText,
  Video,
  BookOpen,
  Mic,
  PlayCircle,
  Eye,
  File
} from 'lucide-react';
import { ContentItem, ContentType, ContentCategory } from '../../types';
import { MOCK_CONTENT, CONTENT_CATEGORIES, CONTENT_TYPES } from '../../constants';
import ContentModal from './ContentModal';
import ContentDetailModal from './ContentDetailModal';

const ContentView: React.FC = () => {
  // State
  const [contents, setContents] = useState<ContentItem[]>(MOCK_CONTENT);
  const [searchQuery, setSearchQuery] = useState('');
  const [showDeleted, setShowDeleted] = useState(false);
  const [filterType, setFilterType] = useState<string>('Todos');
  const [filterCategory, setFilterCategory] = useState<string>('Todas');

  // Modal States
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [isDetailModalOpen, setIsDetailModalOpen] = useState(false);
  const [selectedContent, setSelectedContent] = useState<ContentItem | null>(null);

  // Handlers
  const handleAdd = () => {
    setSelectedContent(null);
    setIsEditModalOpen(true);
  };

  const handleEdit = (item: ContentItem) => {
    setSelectedContent(item);
    setIsEditModalOpen(true);
  };

  const handleView = (item: ContentItem) => {
    setSelectedContent(item);
    setIsDetailModalOpen(true);
  };

  const handleSave = (data: Omit<ContentItem, 'id' | 'isDeleted' | 'createdAt'>) => {
    if (selectedContent && isEditModalOpen) {
      // Update existing
      setContents(prev => prev.map(item => 
        item.id === selectedContent.id ? { ...item, ...data } : item
      ));
    } else {
      // Create new
      const newContent: ContentItem = {
        ...data,
        id: Math.random().toString(36).substr(2, 9),
        createdAt: new Date().toISOString().split('T')[0],
        isDeleted: false
      };
      setContents(prev => [newContent, ...prev]);
    }
  };

  const toggleDelete = (id: string) => {
    setContents(prev => prev.map(item => {
      if (item.id === id) {
        return { ...item, isDeleted: !item.isDeleted };
      }
      return item;
    }));
  };

  const handleDeletePermanent = (id: string) => {
    if (confirm('Tem a certeza que deseja eliminar permanentemente este conteúdo?')) {
      setContents(prev => prev.filter(item => item.id !== id));
    }
  };

  // Filter Logic
  const filteredContents = useMemo(() => {
    return contents.filter(item => {
        if (!showDeleted && item.isDeleted) return false;
        if (showDeleted && !item.isDeleted) return false;

        const matchesSearch = item.title.toLowerCase().includes(searchQuery.toLowerCase());
        const matchesType = filterType === 'Todos' || item.type === filterType;
        const matchesCategory = filterCategory === 'Todas' || item.category === filterCategory;

        return matchesSearch && matchesType && matchesCategory;
    }).sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
  }, [contents, searchQuery, showDeleted, filterType, filterCategory]);

  const getTypeIcon = (type: ContentType) => {
    switch (type) {
      case 'video': return <Video size={14} />;
      case 'article': return <BookOpen size={14} />;
      case 'pdf': return <File size={14} />;
      case 'audio': return <Mic size={14} />;
      default: return <FileText size={14} />;
    }
  };

  const getTypeStyles = (type: ContentType) => {
    switch(type) {
        case 'video': return 'bg-red-50 text-red-600 dark:bg-red-900/20 dark:text-red-400 border-red-100 dark:border-red-900/50';
        case 'article': return 'bg-emerald-50 text-emerald-600 dark:bg-emerald-900/20 dark:text-emerald-400 border-emerald-100 dark:border-emerald-900/50';
        case 'pdf': return 'bg-amber-50 text-amber-600 dark:bg-amber-900/20 dark:text-amber-400 border-amber-100 dark:border-amber-900/50';
        case 'audio': return 'bg-purple-50 text-purple-600 dark:bg-purple-900/20 dark:text-purple-400 border-purple-100 dark:border-purple-900/50';
        default: return 'bg-slate-50 text-slate-600 dark:bg-slate-800 dark:text-slate-400 border-slate-200';
    }
  };

  const getActionButtonConfig = (type: ContentType) => {
      switch(type) {
          case 'video': return { label: 'Ver Vídeo', icon: PlayCircle };
          case 'pdf': return { label: 'Ver PDF', icon: Eye };
          case 'audio': return { label: 'Ouvir', icon: PlayCircle };
          default: return { label: 'Ler Artigo', icon: Eye };
      }
  };

  return (
    <div className="space-y-6 animate-fade-in pb-20">

      {/* Top Toolbar */}
      <div className="glass-card rounded-2xl p-4 flex flex-col md:flex-row justify-between items-center gap-4 sticky top-0 z-20">

        {/* Left: Search & Filters */}
        <div className="flex flex-col sm:flex-row gap-3 w-full md:w-auto">
          <div className="relative group min-w-[240px]">
            <Search size={18} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-primary-500 transition-colors" />
            <input 
              type="text" 
              placeholder="Pesquisar conteúdos..." 
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-10 pr-4 py-2.5 bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-primary-500 outline-none transition-all text-sm"
            />
          </div>

          <div className="flex gap-2">
              <select 
                value={filterType}
                onChange={(e) => setFilterType(e.target.value)}
                className="pl-3 pr-8 py-2.5 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm outline-none focus:ring-2 focus:ring-primary-500 cursor-pointer appearance-none text-slate-600 dark:text-slate-300"
              >
                <option value="Todos">Todos os Tipos</option>
                {CONTENT_TYPES.map(c => <option key={c} value={c} className="capitalize">{c}</option>)}
              </select>

              <select 
                value={filterCategory}
                onChange={(e) => setFilterCategory(e.target.value)}
                className="pl-3 pr-8 py-2.5 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-sm outline-none focus:ring-2 focus:ring-primary-500 cursor-pointer appearance-none text-slate-600 dark:text-slate-300"
              >
                <option value="Todas">Todas as Categorias</option>
                {CONTENT_CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
              </select>
          </div>
        </div>

        {/* Right: Actions */}
        <div className="flex gap-3 w-full md:w-auto justify-end">
          <button 
            onClick={() => setShowDeleted(!showDeleted)}
            className={`
              flex items-center justify-center px-4 py-2.5 rounded-xl border text-sm font-medium transition-all
              ${showDeleted 
                ? 'bg-amber-50 border-amber-200 text-amber-600 dark:bg-amber-900/20 dark:border-amber-800 dark:text-amber-400' 
                : 'bg-white border-slate-200 text-slate-500 hover:text-slate-700 dark:bg-slate-800/50 dark:border-slate-700 dark:text-slate-400'}
            `}
          >
            <Trash2 size={16} />
          </button>

          <button 
            onClick={handleAdd}
            className="flex items-center px-5 py-2.5 bg-gradient-to-r from-primary-600 to-primary-500 text-white rounded-xl font-bold text-sm shadow-lg shadow-primary-500/25 hover:shadow-primary-500/40 hover:-translate-y-0.5 active:translate-y-0 transition-all"
          >
            <Plus size={18} className="mr-2" />
            Adicionar
          </button>
        </div>
      </div>

      {/* Main List */}
      <div className="glass-panel border border-slate-200 dark:border-slate-800 rounded-2xl overflow-hidden">
        {/* Table Header */}
        <div className="grid grid-cols-12 gap-4 px-6 py-4 bg-slate-50/80 dark:bg-slate-900/50 border-b border-slate-200 dark:border-slate-800 text-xs font-semibold text-slate-400 uppercase tracking-wider">
          <div className="col-span-1 hidden md:block text-center">ID</div>
          <div className="col-span-2 sm:col-span-2 md:col-span-1 text-center">Capa</div>
          <div className="col-span-5 sm:col-span-5 md:col-span-4">Conteúdo</div>
          <div className="col-span-2 hidden lg:block">Categoria</div>
          <div className="col-span-3 hidden md:block text-center">Acesso</div>
          <div className="col-span-4 sm:col-span-3 md:col-span-2 lg:col-span-1 text-right">Ações</div>
        </div>

        {/* List Items */}
        <div className="divide-y divide-slate-100 dark:divide-slate-800 bg-white/50 dark:bg-slate-900/30">
          {filteredContents.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-20 text-center">
              <div className="w-20 h-20 bg-slate-100 dark:bg-slate-800 rounded-full flex items-center justify-center mb-4">
                 <FileText size={32} className="text-slate-400" />
              </div>
              <h3 className="text-lg font-bold text-slate-700 dark:text-slate-300">Sem conteúdos encontrados</h3>
              <p className="text-slate-500 max-w-xs mt-2 text-sm">Adicione vídeos, artigos ou documentos para a sua biblioteca de recursos.</p>
              <button onClick={handleAdd} className="mt-6 text-primary-600 font-medium hover:underline text-sm">Adicionar Conteúdo</button>
            </div>
          ) : (
            filteredContents.map((item) => {
              const ActionConfig = getActionButtonConfig(item.type);
              const ActionIcon = ActionConfig.icon;

              return (
                <div 
                    key={item.id} 
                    className={`
                    group grid grid-cols-12 gap-4 px-6 py-4 items-center transition-all duration-200 hover:bg-slate-50 dark:hover:bg-slate-800/50
                    ${item.isDeleted ? 'opacity-60 grayscale' : ''}
                    `}
                >
                    {/* ID */}
                    <div className="col-span-1 hidden md:block text-center">
                        <span className="text-xs font-mono text-slate-400">#{item.id}</span>
                    </div>

                    {/* Thumbnail */}
                    <div className="col-span-2 sm:col-span-2 md:col-span-1 flex justify-center">
                        <div className="w-16 aspect-video rounded-lg bg-slate-200 dark:bg-slate-700 overflow-hidden shadow-sm relative group-hover:scale-105 transition-transform cursor-pointer" onClick={() => handleView(item)}>
                            <img src={item.thumbnail} alt={item.title} className="w-full h-full object-cover" />
                            {item.type === 'video' && (
                                <div className="absolute inset-0 flex items-center justify-center bg-black/20">
                                    <div className="w-5 h-5 rounded-full bg-white/90 flex items-center justify-center shadow-md">
                                        <PlayCircle size={10} className="text-red-600 ml-0.5" />
                                    </div>
                                </div>
                            )}
                        </div>
                    </div>

                    {/* Title & Info */}
                    <div className="col-span-5 sm:col-span-5 md:col-span-4">
                        <h3 
                            className="font-bold text-slate-800 dark:text-white text-sm sm:text-base truncate pr-2 cursor-pointer hover:text-primary-500 transition-colors" 
                            title={item.title}
                            onClick={() => handleView(item)}
                        >
                            {item.title}
                        </h3>
                        <div className="flex flex-col items-start gap-1 mt-1">
                            <span className={`flex items-center gap-1 px-2 py-0.5 rounded text-[10px] font-bold uppercase tracking-wider border ${getTypeStyles(item.type)}`}>
                                {getTypeIcon(item.type)} {item.type}
                            </span>
                            <span className="text-[10px] text-slate-400 truncate w-full lg:hidden">
                                {item.description}
                            </span>
                        </div>
                    </div>

                    {/* Category */}
                    <div className="col-span-2 hidden lg:flex flex-col justify-center">
                        <span className="text-sm text-slate-600 dark:text-slate-300 font-medium">
                            {item.category}
                        </span>
                        <span className="text-[10px] text-slate-400">
                             {item.createdAt}
                        </span>
                    </div>

                    {/* View Button (URL Replacement) */}
                    <div className="col-span-3 hidden md:flex justify-center">
                         <button 
                            onClick={() => handleView(item)}
                            className="flex items-center gap-2 px-3 py-1.5 rounded-lg bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 shadow-sm hover:shadow hover:border-primary-300 dark:hover:border-primary-700 transition-all group/btn"
                        >
                            <ActionIcon size={14} className="text-primary-500 group-hover/btn:scale-110 transition-transform" />
                            <span className="text-xs font-medium text-slate-600 dark:text-slate-300 group-hover/btn:text-primary-600 dark:group-hover/btn:text-primary-400">
                                {ActionConfig.label}
                            </span>
                        </button>
                    </div>

                    {/* Actions */}
                    <div className="col-span-4 sm:col-span-3 md:col-span-2 lg:col-span-1 flex justify-end items-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                        {item.isDeleted ? (
                            <>
                                <button 
                                onClick={() => toggleDelete(item.id)}
                                title="Restaurar"
                                className="p-2 text-emerald-600 hover:bg-emerald-50 rounded-lg transition-colors"
                                >
                                <RotateCcw size={18} />
                                </button>
                                <button 
                                onClick={() => handleDeletePermanent(item.id)}
                                title="Eliminar Permanentemente"
                                className="p-2 text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                                >
                                <Trash2 size={18} />
                                </button>
                            </>
                        ) : (
                            <>
                                <button 
                                onClick={() => handleEdit(item)}
                                className="p-2 text-slate-500 hover:text-primary-600 hover:bg-primary-50 dark:hover:bg-primary-900/20 rounded-lg transition-colors"
                                >
                                <Edit2 size={18} />
                                </button>
                                <button 
                                onClick={() => toggleDelete(item.id)}
                                className="p-2 text-slate-500 hover:text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition-colors"
                                >
                                <Trash2 size={18} />
                                </button>
                                {/* Mobile View Button */}
                                <button 
                                  onClick={() => handleView(item)}
                                  className="p-2 text-slate-500 hover:text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded-lg transition-colors md:hidden"
                                >
                                  <Eye size={18} />
                                </button>
                            </>
                        )}
                    </div>
                </div>
              );
            })
          )}
        </div>

        {/* Footer / Pagination */}
        <div className="px-6 py-4 border-t border-slate-200 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-900/50 flex justify-between items-center">
          <p className="text-xs text-slate-500 dark:text-slate-400">
            A mostrar {filteredContents.length} resultados
          </p>
          <div className="flex gap-2">
            <button disabled className="px-3 py-1 text-xs font-medium rounded-lg border border-slate-200 dark:border-slate-700 text-slate-400 cursor-not-allowed">Anterior</button>
            <button className="px-3 py-1 text-xs font-medium rounded-lg bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-300 hover:border-primary-500 hover:text-primary-500 transition-colors">1</button>
            <button className="px-3 py-1 text-xs font-medium rounded-lg bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-slate-700">2</button>
            <button className="px-3 py-1 text-xs font-medium rounded-lg bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-slate-700">Seguinte</button>
          </div>
        </div>
      </div>

      <ContentModal 
        isOpen={isEditModalOpen}
        onClose={() => setIsEditModalOpen(false)}
        onSave={handleSave}
        initialData={selectedContent}
      />

      <ContentDetailModal
        isOpen={isDetailModalOpen}
        onClose={() => setIsDetailModalOpen(false)}
        content={selectedContent}
      />
    </div>
  );
};

